// Number formatting — refined, terse, signed, and humane.
const _nfCompact = new Intl.NumberFormat("en-US", { notation: "compact", maximumFractionDigits: 1 });
const _nfFull    = new Intl.NumberFormat("en-US");
const fmt = {
  num:     (n) => (n == null ? "—" : _nfFull.format(n)),
  compact: (n) => (n == null ? "—" : _nfCompact.format(n)),
  pct:     (n, d = 1) => (n == null ? "—" : `${n.toFixed(d)}%`),
  signedPct: (n, d = 2) => (n == null ? "—" : `${n >= 0 ? "+" : ""}${n.toFixed(d)}%`),
  signedNum: (n) => (n == null ? "—" : `${n >= 0 ? "+" : ""}${_nfFull.format(n)}`),
  abs:     (n) => Math.abs(n),
  arrow:   (n) => (n > 0 ? "↑" : n < 0 ? "↓" : "→"),
  money:   (n, d = 2) => (n == null ? "—" : `$${n.toFixed(d)}`),
  moneyK:  (n) => (n == null ? "—" : `$${_nfCompact.format(n)}`),
};

