// Inline badge for non-confirmed event status (standing rule #4 — fact/inference/unknown visibly separate).
// Confirmed items render nothing; REPORTED = amber; DISPUTED/UNKNOWN = red-outline.
const StatusBadge = ({ status }) => {
  if (!status || status === 'confirmed') return null;
  const disputed = status === 'disputed' || status === 'unknown';
  return (
    <span title={disputed ? "Disputed — credible sources materially disagree" : "Reported — single credible source, not independently confirmed"} style={{
      display:"inline-block", marginRight:6, verticalAlign:"middle",
      fontSize:FS.xs, fontWeight:700,
      color: disputed ? DANGER : AMBER,
      background: disputed ? "transparent" : alpha(AMBER, .14),
      border:`1px solid ${disputed ? alpha(DANGER, .45) : alpha(AMBER, .35)}`,
      padding:"1px 5px", borderRadius:4,
      letterSpacing:".08em", lineHeight:1.3, cursor:"help",
    }}>
      {disputed ? "DISPUTED" : "REPORTED"}
    </span>
  );
};

