function AITab({ targetArc = null, onConsumeTarget } = {}) {
  // Latest updated_at across cards = most recently refreshed card.
  // Format: "MM/DD/YYYY · HH:MM TZ"; we sort by parsed date only (time/TZ is informational).
  const parseUpdatedAt = (s) => {
    if (!s) return -1;
    const m = s.match(/^(\d{2})\/(\d{2})\/(\d{4})/);
    if (!m) return -1;
    return new Date(Number(m[3]), Number(m[1]) - 1, Number(m[2])).getTime();
  };
  const latest = AI_CARDS.reduce((acc, c) => {
    const t = parseUpdatedAt(c.updated_at);
    return t > acc.t ? { t, label: c.updated_at } : acc;
  }, { t: -1, label: "—" });

  // Deep-link from an Overview lead card: scroll to + briefly highlight the first
  // card whose arc matches the incoming target, then clear the target so it fires once.
  // The scroll + ring are applied IMPERATIVELY (not via React state) so a re-render
  // can't clobber them: the wrapper's React style never sets boxShadow, so React
  // leaves our imperative value alone until we clear it.
  const cardRefs = useRef({});
  useEffect(() => {
    if (!targetArc) return;
    const hit = AI_CARDS.find(c => c.arc === targetArc);
    if (!hit) { if (onConsumeTarget) onConsumeTarget(); return; }
    // Small defer lets the freshly-mounted Analysis panel paint before we scroll.
    const t = setTimeout(() => {
      const el = cardRefs.current[hit.lens];
      if (el) {
        if (el.scrollIntoView) el.scrollIntoView({ behavior: "smooth", block: "start" });
        el.style.boxShadow = `0 0 0 2px ${hit.color}, 0 0 22px ${alpha(hit.color, .35)}`;
        setTimeout(() => { if (cardRefs.current[hit.lens]) cardRefs.current[hit.lens].style.boxShadow = ""; }, 2400);
      }
      if (onConsumeTarget) onConsumeTarget();
    }, 70);
    return () => clearTimeout(t);
  }, [targetArc]);

  return (
    <div style={{ display:"flex", flexDirection:"column", gap:16 }}>
      <div style={{ display:"flex", alignItems:"center", gap:12, padding:"14px 18px", background:alpha(VIOLET, .08), border:`1px solid ${alpha(VIOLET, .22)}`, borderRadius:12 }}>
        <span style={{ width:8, height:8, borderRadius:"50%", background:VIOLET, animation:"ping 1.5s ease infinite", flexShrink:0 }} />
        <M style={{ fontSize:12, color:VIOLET, letterSpacing:".06em", fontWeight:600 }}>AI Strategic Analysis · Claude Opus 4.7</M>
        <span style={{ width:1, height:14, background:alpha(VIOLET, .25) }} />
        <M style={{ fontSize:12, color:TEXT_BODY, fontWeight:500 }}>Epic Fury · US-BRICS Rivalry · Russia-Ukraine</M>
        <M style={{ fontSize:11, color:TEXT_DIM, marginLeft:"auto", fontVariantNumeric:"tabular-nums" }}>Latest card: {latest.label}</M>
      </div>
      {AI_CARDS.map(c => (
        <div
          key={c.lens}
          ref={el => { cardRefs.current[c.lens] = el; }}
          style={{ borderRadius:14, scrollMarginTop:80, transition:"box-shadow .35s ease" }}
        >
          <AICard c={c} />
        </div>
      ))}
    </div>
  );
}

// Single Analysis card: plain-language summary by default; the detailed
// briefing (body) expands on demand. Keeps the scannable read up top and the
// depth one click away.
function AICard({ c }) {
  const [expanded, setExpanded] = useState(false);
  const confColor = c.confidence === "HIGH" ? GREEN : c.confidence === "MODERATE" ? AMBER : DANGER;
  const hasBody = !!(c.body && c.body.trim());
  const hasSummary = !!(c.summary && c.summary.trim());
  // Fallback: a card with no summary keeps the old always-on body.
  const showBody = expanded || !hasSummary;
  return (
    <Card style={{ borderLeft:`3px solid ${c.color}` }}>
      <div style={{ display:"flex", alignItems:"center", gap:10, marginBottom:8, flexWrap:"wrap" }}>
        <span style={{ fontSize:18 }}>{c.icon}</span>
        <M style={{ fontSize:FS.xs, color:c.color, letterSpacing:".14em", fontWeight:600, textTransform:"uppercase" }}>{c.lens}</M>
        {c.updated_at && (
          <M style={{ fontSize:FS.xs, color:TEXT_DIM, fontVariantNumeric:"tabular-nums" }}>{c.updated_at}</M>
        )}
        {c.confidence && (
          <span style={{
            display:"inline-flex", alignItems:"center", gap:6,
            fontSize:FS.xs, fontWeight:600, letterSpacing:".12em", textTransform:"uppercase",
            color: confColor, padding:"2px 9px", borderRadius:999,
            background: alpha(confColor, .10), border:`1px solid ${alpha(confColor, .28)}`,
            marginLeft:"auto",
          }}>
            <span style={{ width:5, height:5, borderRadius:"50%", background:confColor }} />
            {c.confidence} confidence
            {c.confidenceNote && <InfoTip>{c.confidenceNote}</InfoTip>}
          </span>
        )}
      </div>
      <div style={{ fontSize:18, fontWeight:600, color:TEXT_HI, marginBottom:14, letterSpacing:"-.01em", lineHeight:1.3 }}>{c.title}</div>
      {/* bottom_line RETIRED 2026-08-26 (operator decision) — see LeadCard note. */}
      {hasSummary && (
        <div style={{ fontSize:14.5, color:TEXT_HI, lineHeight:1.65, fontWeight:450 }}>{linkifyText(c.summary)}</div>
      )}
      {hasBody && hasSummary && (
        <button
          onClick={() => setExpanded(v => !v)}
          className="pressable"
          style={{
            background:"none", border:"none", padding:0, marginTop:12,
            color:c.color, fontSize:12, fontWeight:600, letterSpacing:".04em", cursor:"pointer",
            display:"inline-flex", alignItems:"center", gap:6, alignSelf:"flex-start",
          }}
        >{expanded ? "− Hide full analysis" : "+ Read full analysis"}</button>
      )}
      {hasBody && showBody && (
        <div style={{ display:"flex", flexDirection:"column", gap:14, marginTop: hasSummary ? 14 : 0, paddingTop: hasSummary ? 14 : 0, borderTop: hasSummary ? `1px solid ${BORDER}` : "none" }}>
          {c.body.split("\n\n").map((para, i) => {
            const [head, ...rest] = para.split(": ");
            if (rest.length && head === head.toUpperCase() && head.length < 30) {
              return (
                <div key={i}>
                  <M style={{ fontSize:11, color:c.color, fontWeight:600, letterSpacing:".12em", display:"block", marginBottom:6, textTransform:"uppercase" }}>{head}</M>
                  <div style={{ fontSize:14, color:TEXT_BODY, lineHeight:1.7 }}>{linkifyText(rest.join(": "))}</div>
                </div>
              );
            }
            return <div key={i} style={{ fontSize:14, color:TEXT_BODY, lineHeight:1.7 }}>{linkifyText(para)}</div>;
          })}
        </div>
      )}
    </Card>
  );
}

// ── Outlook tab ─────────────────────────────────────────────────────────────
// Surfaces the forecasting registry the daily pipeline keeps internally: open
// forecasts (with probability history), the resolved-forecast track record +
// calibration, leading indicators (escalation vs de-escalation), and open
// intelligence gaps. Reads the reader-safe __DATA__.outlook projection.

const OUT_PROB_COLOR = (p) => (p >= 0.66 ? DANGER : p >= 0.34 ? AMBER : GREEN);

function fmtResolve(dateStr) {
  if (!dateStr) return null;
  const d = new Date(dateStr + "T00:00:00");
  if (isNaN(d.getTime())) return null;
  const days = Math.ceil((d - NOW) / 86400000);
  const label = d.toLocaleDateString("en-US", { month:"short", day:"numeric" });
  if (days < 0) return { label, sub:"closed", over:true };
  if (days === 0) return { label, sub:"today", soon:true };
  if (days === 1) return { label, sub:"1 day", soon:true };
  return { label, sub:`${days} days`, soon: days <= 7 };
}

const OutTheaterChip = ({ name }) => name ? (
  <M style={{ fontSize:FS.xs, color:TEXT_DIM, letterSpacing:".08em", textTransform:"uppercase", fontWeight:600, background:RAISE_2, border:`1px solid ${BORDER}`, borderRadius:999, padding:"2px 8px", whiteSpace:"nowrap" }}>{name}</M>
) : null;

// One open forecast — probability, deadline countdown, probability-history
// sparkline; expands to resolution criteria / latest read / disconfirmation note.
function ForecastRow({ f, openCountry }) {
  const [open, setOpen] = useState(false);
  const p = f.probability;
  const pc = OUT_PROB_COLOR(p);
  const dl = fmtResolve(f.deadline);
  const hasDetail = !!(f.resolution_criteria || f.surprise_if_wrong || f.latest_reason);
  return (
    <Card className="card-hover" style={{ padding:16 }}>
      <div onClick={hasDetail ? () => setOpen(v=>!v) : undefined} style={{ display:"flex", gap:14, alignItems:"flex-start", cursor: hasDetail ? "pointer" : "default" }}>
        <div style={{ width:34, flexShrink:0, textAlign:"right", paddingTop:1 }}>
          <M style={{ fontSize:15, fontWeight:600, color:pc, fontVariantNumeric:"tabular-nums", lineHeight:1 }}>{Math.round(p*100)}<span style={{ fontSize:FS.xs, color:TEXT_DIM, fontWeight:600 }}>%</span></M>
        </div>
        <div style={{ flex:1, minWidth:0 }}>
          <div style={{ fontSize:13.5, color:TEXT_HI, lineHeight:1.5, fontWeight:500 }}>{linkifyText(f.question, openCountry)}</div>
          <div style={{ display:"flex", alignItems:"center", gap:8, marginTop:8, flexWrap:"wrap" }}>
            <OutTheaterChip name={f.theater} />
            {dl && <M style={{ fontSize:11, color:TEXT_MID, fontVariantNumeric:"tabular-nums" }}>resolves {dl.label} · <span style={{ color: dl.over ? TEXT_DIM : dl.soon ? AMBER : TEXT_MID }}>{dl.sub}</span></M>}
            {hasDetail && <M style={{ fontSize:11, color:pc, fontWeight:600 }}>{open ? "− less" : "details +"}</M>}
          </div>
        </div>
      </div>
      {open && hasDetail && (
        <div style={{ marginTop:14, paddingTop:14, borderTop:`1px solid ${BORDER}`, display:"flex", flexDirection:"column", gap:11 }}>
          {f.resolution_criteria && (<div><Eyebrow mb={5} color={BLUE}>How it resolves</Eyebrow><div style={{ fontSize:12.5, color:TEXT_BODY, lineHeight:1.6 }}>{linkifyText(f.resolution_criteria, openCountry)}</div></div>)}
          {f.latest_reason && (<div><Eyebrow mb={5}>Latest read</Eyebrow><div style={{ fontSize:12.5, color:TEXT_BODY, lineHeight:1.6 }}>{linkifyText(f.latest_reason, openCountry)}</div></div>)}
          {f.surprise_if_wrong && (<div><Eyebrow mb={5} color={AMBER}>What it would mean if wrong</Eyebrow><div style={{ fontSize:12.5, color:TEXT_BODY, lineHeight:1.6 }}>{linkifyText(f.surprise_if_wrong, openCountry)}</div></div>)}
        </div>
      )}
    </Card>
  );
}

// Resolved-forecast track record + calibration. Brier and reliability buckets
// are derived in scripts/build.js from real outcomes (no synthetic data).
function CalibrationPanel({ cal }) {
  const [showResolved, setShowResolved] = useState(false);
  if (!cal || !cal.total_resolved) return null;
  const brier = cal.brier;
  const brierColor = brier == null ? TEXT_MID : brier <= 0.18 ? GREEN : brier <= 0.25 ? AMBER : DANGER;
  const liveBuckets = (cal.buckets || []).filter(b => b.predicted > 0);
  const resolved = cal.resolved || [];
  const hits = resolved.filter(r => r.hit).length;
  return (
    <Card style={{ padding:22 }}>
      <div style={{ display:"flex", alignItems:"center", gap:10, marginBottom:18, flexWrap:"wrap" }}>
        <div style={{ fontSize:11, color:TEXT_DIM, letterSpacing:".12em", fontWeight:600, textTransform:"uppercase" }}>Track Record · Calibration</div>
        <SourceBadge kind="scenario" />
      </div>
      <div style={{ display:"flex", gap:30, flexWrap:"wrap", marginBottom: liveBuckets.length ? 20 : 4 }}>
        <div>
          <M className="display" style={{ fontSize:30, fontWeight:600, color:TEXT_HI, letterSpacing:"-.025em", lineHeight:1 }}>{cal.total_resolved}</M>
          <div style={{ fontSize:11, color:TEXT_DIM, marginTop:5 }}>forecasts resolved</div>
        </div>
        <div>
          <M className="display" style={{ fontSize:30, fontWeight:600, color:TEXT_HI, letterSpacing:"-.025em", lineHeight:1 }}>{hits}<span style={{ fontSize:16, color:TEXT_DIM, fontWeight:500 }}>/{cal.total_resolved}</span></M>
          <div style={{ fontSize:11, color:TEXT_DIM, marginTop:5 }}>called correctly</div>
        </div>
        <div>
          <M className="display" style={{ fontSize:30, fontWeight:600, color:brierColor, letterSpacing:"-.025em", lineHeight:1 }}>{brier == null ? "—" : brier.toFixed(2)}</M>
          <div style={{ fontSize:11, color:TEXT_DIM, marginTop:5, display:"inline-flex", alignItems:"center" }}>Brier score<InfoTip>Mean squared error of each forecast's opening probability against what actually happened. Lower is better; 0.25 is what you'd score always guessing 50%.</InfoTip></div>
        </div>
      </div>
      {liveBuckets.length > 0 && (
        <div style={{ display:"flex", flexDirection:"column", gap:9 }}>
          <Eyebrow mb={2}>Reliability — of the calls we rated…</Eyebrow>
          {liveBuckets.map(b => {
            const rate = b.predicted ? b.occurred / b.predicted : 0;
            return (
              <div key={b.label} style={{ display:"flex", alignItems:"center", gap:12 }}>
                <M style={{ width:64, fontSize:11.5, color:TEXT_MID, fontVariantNumeric:"tabular-nums", flexShrink:0 }}>{b.label}</M>
                <div style={{ flex:1, height:6, background:RAISE_2, borderRadius:999, overflow:"hidden", minWidth:60 }}>
                  <div style={{ width:`${Math.round(rate*100)}%`, height:"100%", background:BLUE, borderRadius:999, transition:"width .6s cubic-bezier(.2,.8,.2,1)" }} />
                </div>
                <M style={{ width:126, fontSize:11, color:TEXT_DIM, textAlign:"right", flexShrink:0, fontVariantNumeric:"tabular-nums" }}>{b.occurred} of {b.predicted} happened</M>
              </div>
            );
          })}
        </div>
      )}
      {resolved.length > 0 && (
        <>
          <button onClick={() => setShowResolved(v=>!v)} className="pressable" style={{ background:"none", border:"none", padding:0, marginTop:16, color:BLUE, fontSize:12, fontWeight:600, cursor:"pointer", display:"inline-flex", alignSelf:"flex-start" }}>
            {showResolved ? "− Hide resolved forecasts" : `+ Show all ${resolved.length} resolved forecasts`}
          </button>
          {showResolved && (
            <div style={{ marginTop:13, display:"flex", flexDirection:"column", gap:9 }}>
              {resolved.map((r, i) => (
                <div key={i} style={{ display:"flex", gap:10, alignItems:"flex-start", fontSize:12.5, lineHeight:1.55 }}>
                  <span style={{ flexShrink:0, color: r.hit ? GREEN : DANGER, fontWeight:700, width:13 }}>{r.hit ? "✓" : "✗"}</span>
                  <div style={{ flex:1, minWidth:0, color:TEXT_BODY }}>
                    {scrubCodes(r.question)}
                    <M style={{ color:TEXT_DIM, marginLeft:6, fontSize:11, whiteSpace:"nowrap" }}>called {Math.round(r.initial_probability*100)}% · {r.occurred ? "happened" : "did not"}</M>
                  </div>
                </div>
              ))}
            </div>
          )}
        </>
      )}
    </Card>
  );
}

// One leading indicator — compact one-line row (escalation/de-escalation tag +
// signal %); expands to the signal bar, activation threshold, watch window and
// latest evidence.
function IndicatorRow({ ind, openCountry }) {
  const [open, setOpen] = useState(false);
  const esc = ind.type !== "de-escalation";
  const col = esc ? DANGER : GREEN;
  const sig = typeof ind.signal === "number" ? ind.signal : 0;
  const thr = typeof ind.threshold === "number" ? ind.threshold : null;
  const hasDetail = !!(thr != null || ind.watch_window_end || ind.latest_evidence || ind.theater);
  return (
    <Card className={hasDetail ? "card-hover" : undefined} style={{ padding:"10px 14px", borderLeft:`3px solid ${alpha(col,.55)}` }}>
      <div onClick={hasDetail ? () => setOpen(v=>!v) : undefined} style={{ display:"flex", alignItems:"center", gap:10, cursor: hasDetail ? "pointer" : "default" }}>
        <M style={{ fontSize:FS.xs, fontWeight:700, letterSpacing:".1em", textTransform:"uppercase", color:col, flexShrink:0, minWidth:46 }}>{esc ? "Esc" : "De-esc"}</M>
        <div style={{ flex:1, minWidth:0, fontSize:12.5, color:TEXT_HI, fontWeight:500, whiteSpace:"nowrap", overflow:"hidden", textOverflow:"ellipsis" }}>{linkifyText(ind.indicator, openCountry)}</div>
        <M style={{ fontSize:11, color:col, fontWeight:600, fontVariantNumeric:"tabular-nums", flexShrink:0 }}>{Math.round(sig*100)}%</M>
        {hasDetail && <M style={{ fontSize:11, color:TEXT_DIM, flexShrink:0, width:9, textAlign:"center" }}>{open ? "−" : "+"}</M>}
      </div>
      {open && hasDetail && (
        <div style={{ marginTop:10, paddingTop:10, borderTop:`1px solid ${BORDER}`, display:"flex", flexDirection:"column", gap:9 }}>
          {ind.theater && <div><OutTheaterChip name={ind.theater} /></div>}
          <div style={{ position:"relative", height:6, background:RAISE_2, borderRadius:999 }}>
            <div style={{ width:`${Math.round(sig*100)}%`, height:"100%", background:col, borderRadius:999, transition:"width .6s cubic-bezier(.2,.8,.2,1)" }} />
            {thr != null && (
              <div title={`Activates at ${Math.round(thr*100)}%`} style={{ position:"absolute", left:`${Math.round(thr*100)}%`, top:-3, width:2, height:12, background:TEXT_HI, opacity:.45, borderRadius:2 }} />
            )}
          </div>
          <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", gap:8 }}>
            <M style={{ fontSize:11, color:col, fontWeight:600, fontVariantNumeric:"tabular-nums" }}>signal {Math.round(sig*100)}%{thr != null && <span style={{ color:TEXT_DIM, fontWeight:500 }}> · fires at {Math.round(thr*100)}%</span>}</M>
            {ind.watch_window_end && <M style={{ fontSize:FS.xs, color:TEXT_DIM, fontVariantNumeric:"tabular-nums" }}>watch thru {new Date(ind.watch_window_end+"T00:00:00").toLocaleDateString("en-US",{month:"short",day:"numeric"})}</M>}
          </div>
          {ind.latest_evidence && <div style={{ fontSize:12, color:TEXT_BODY, lineHeight:1.55 }}>{linkifyText(ind.latest_evidence, openCountry)}</div>}
        </div>
      )}
    </Card>
  );
}

const GAP_PRI = { critical:{ c:DANGER, label:"Critical" }, important:{ c:AMBER, label:"Important" }, monitoring:{ c:BLUE, label:"Monitoring" } };
// One open intelligence gap — compact one-line row (priority tag, question,
// days-open); expands to why-it-matters and current collection status.
function GapRow({ g, openCountry }) {
  const [open, setOpen] = useState(false);
  const pri = GAP_PRI[g.priority] || { c:TEXT_MID, label:g.priority };
  const hasDetail = !!(g.why_it_matters || g.collection_status || g.theater);
  return (
    <Card className={hasDetail ? "card-hover" : undefined} style={{ padding:"10px 14px", borderLeft:`3px solid ${alpha(pri.c,.55)}` }}>
      <div onClick={hasDetail ? () => setOpen(v=>!v) : undefined} style={{ display:"flex", alignItems:"center", gap:10, cursor: hasDetail ? "pointer" : "default" }}>
        <M style={{ fontSize:FS.xs, fontWeight:700, letterSpacing:".1em", textTransform:"uppercase", color:pri.c, flexShrink:0, minWidth:64 }}>{pri.label}</M>
        <div style={{ flex:1, minWidth:0, fontSize:12.5, color:TEXT_HI, fontWeight:500, whiteSpace:"nowrap", overflow:"hidden", textOverflow:"ellipsis" }}>{linkifyText(g.question, openCountry)}</div>
        {g.days_open != null && <M style={{ fontSize:FS.xs, color:TEXT_DIM, flexShrink:0, fontVariantNumeric:"tabular-nums" }}>open {g.days_open}d</M>}
        {hasDetail && <M style={{ fontSize:11, color:TEXT_DIM, flexShrink:0, width:9, textAlign:"center" }}>{open ? "−" : "+"}</M>}
      </div>
      {open && hasDetail && (
        <div style={{ marginTop:10, paddingTop:10, borderTop:`1px solid ${BORDER}`, display:"flex", flexDirection:"column", gap:8 }}>
          {g.theater && <div><OutTheaterChip name={g.theater} /></div>}
          {g.why_it_matters && <div style={{ fontSize:12.5, color:TEXT_BODY, lineHeight:1.6 }}>{linkifyText(g.why_it_matters, openCountry)}</div>}
          {g.collection_status && <div style={{ fontSize:12, color:TEXT_DIM, lineHeight:1.55, fontStyle:"italic" }}>{linkifyText(g.collection_status, openCountry)}</div>}
        </div>
      )}
    </Card>
  );
}

function OutlookTab({ openCountry }) {
  const data = OUTLOOK || {};
  const [showAllFc, setShowAllFc] = useState(false);
  const FC_CAP = 6;
  const forecasts = Array.isArray(data.forecasts) ? data.forecasts : [];
  const openForecasts = forecasts
    .filter(f => f.status === "open")
    .sort((a,b) => (a.deadline || "9999-12-31").localeCompare(b.deadline || "9999-12-31"));
  const indicators = Array.isArray(data.indicators) ? data.indicators : [];
  const escalators = indicators.filter(i => i.type !== "de-escalation").sort((a,b)=>(b.signal||0)-(a.signal||0));
  const deescalators = indicators.filter(i => i.type === "de-escalation").sort((a,b)=>(b.signal||0)-(a.signal||0));
  const gaps = Array.isArray(data.gaps) ? data.gaps : [];
  const PRI_ORDER = { critical:0, important:1, monitoring:2 };
  const sortedGaps = [...gaps].sort((a,b) => (PRI_ORDER[a.priority] ?? 3) - (PRI_ORDER[b.priority] ?? 3) || (b.days_open||0) - (a.days_open||0));

  const SectionHead = ({ children, count }) => (
    <div style={{ display:"flex", alignItems:"center", gap:10, paddingLeft:2, flexWrap:"wrap" }}>
      <div style={{ fontSize:11, color:TEXT_DIM, letterSpacing:".12em", fontWeight:600, textTransform:"uppercase" }}>{children}</div>
      {count != null && <M style={{ fontSize:11, color:TEXT_DIM, fontVariantNumeric:"tabular-nums" }}>{count}</M>}
      <SourceBadge kind="scenario" />
    </div>
  );

  const empty = openForecasts.length === 0 && indicators.length === 0 && sortedGaps.length === 0 && !(data.calibration && data.calibration.total_resolved);

  return (
    <div style={{ display:"flex", flexDirection:"column", gap:20 }}>
      <div style={{ display:"flex", alignItems:"center", gap:12, padding:"14px 18px", background:alpha(BLUE,.07), border:`1px solid ${alpha(BLUE,.22)}`, borderRadius:12, flexWrap:"wrap" }}>
        <span style={{ display:"inline-flex", color:BLUE }}><Icon name="outlook" size={18} /></span>
        <M style={{ fontSize:12, color:BLUE, letterSpacing:".06em", fontWeight:600 }}>Outlook · Forecasts &amp; Track Record</M>
        <span style={{ width:1, height:14, background:alpha(BLUE,.25) }} />
        <M style={{ fontSize:12, color:TEXT_BODY, fontWeight:500 }}>Named, dated, falsifiable calls — scored against what actually happened.</M>
      </div>

      <CalibrationPanel cal={data.calibration} />

      {openForecasts.length > 0 && (
        <div style={{ display:"flex", flexDirection:"column", gap:12 }}>
          <SectionHead count={openForecasts.length}>Open Forecasts · Soonest First</SectionHead>
          {(showAllFc ? openForecasts : openForecasts.slice(0, FC_CAP)).map((f,i) => <ForecastRow key={i} f={f} openCountry={openCountry} />)}
          {openForecasts.length > FC_CAP && (
            <button onClick={() => setShowAllFc(v=>!v)} className="pressable" style={{ background:"none", border:"none", padding:0, marginTop:2, color:BLUE, fontSize:12, fontWeight:600, cursor:"pointer", display:"inline-flex", alignSelf:"flex-start" }}>
              {showAllFc ? "− Show fewer" : `+ Show all ${openForecasts.length} forecasts`}
            </button>
          )}
        </div>
      )}

      {(escalators.length > 0 || deescalators.length > 0) && (
        <div style={{ display:"flex", flexDirection:"column", gap:12 }}>
          <SectionHead count={indicators.length}>Leading Indicators · Escalation &amp; De-escalation</SectionHead>
          <div style={{ display:"flex", flexDirection:"column", gap:6 }}>
            {escalators.map((ind,i) => <IndicatorRow key={`e${i}`} ind={ind} openCountry={openCountry} />)}
            {deescalators.map((ind,i) => <IndicatorRow key={`d${i}`} ind={ind} openCountry={openCountry} />)}
          </div>
        </div>
      )}

      {sortedGaps.length > 0 && (
        <div style={{ display:"flex", flexDirection:"column", gap:12 }}>
          <SectionHead count={sortedGaps.length}>Open Questions · What We're Still Confirming</SectionHead>
          <div style={{ display:"flex", flexDirection:"column", gap:6 }}>
            {sortedGaps.map((g,i) => <GapRow key={i} g={g} openCountry={openCountry} />)}
          </div>
        </div>
      )}

      {empty && (
        <Card style={{ padding:24 }}><div style={{ fontSize:13, color:TEXT_DIM }}>No forecasts, indicators, or intelligence gaps are currently being tracked.</div></Card>
      )}
    </div>
  );
}

// ── Live-price reliability layer ───────────────────────────────────────────
// Shared by Yahoo Finance (markets) and AAA (gas). Solves four prior problems:
//   1. Slow proxies hung forever (no fetch timeout)
//   2. Proxy fallback was all-or-nothing per proxy (one failed URL poisoned the cycle)
//   3. No localStorage cache → cold reload showed skeleton until the first fetch
//   4. No periodic refresh → a failed initial mount fetch never recovered
const FETCH_TIMEOUT_MS = 8000;
async function fetchWithTimeout(url, ms = FETCH_TIMEOUT_MS, opts = {}) {
  const ac = new AbortController();
  const t = setTimeout(() => ac.abort(), ms);
  try {
    return await fetch(url, { ...opts, signal: ac.signal });
  } finally {
    clearTimeout(t);
  }
}

// localStorage-backed cache of the last-known-good price for each instrument.
// Schema: { BRENT:{price,chg,asOf}, gas:{national,california,ohio,cincinnati,asOf}, _ts }
// Used to hydrate state on mount (instant first paint with stale label) and updated
// on each successful fetch.
const PRICE_CACHE_KEY = "ww3dash.priceCache.v1";
const priceCache = {
  read() {
    try { return JSON.parse(localStorage.getItem(PRICE_CACHE_KEY) || "{}") || {}; }
    catch { return {}; }
  },
  write(patch) {
    try {
      const cur = priceCache.read();
      const next = { ...cur, ...patch, _ts: Date.now() };
      localStorage.setItem(PRICE_CACHE_KEY, JSON.stringify(next));
    } catch (_) {}
  },
};

// Per-reader "last visit" timestamp powering the "Since your last visit" panel.
// Pure client state — never touches data freshness / meta (Standing Rule:
// "timestamp follows data"). Read the prior value on mount, then overwrite with
// now so the NEXT visit diffs against this one.
const VISIT_KEY = "ww3dash.lastVisit.v1";
const visitStore = {
  read() { try { return localStorage.getItem(VISIT_KEY) || null; } catch { return null; } },
  write() { try { localStorage.setItem(VISIT_KEY, new Date().toISOString()); } catch (_) {} },
};

// Per-day rolling time series for the Economy gas chart so Ohio + Cincinnati
// can build up live data over time without violating the no-synthetic-data rule.
// Schema: [{date:"YYYY-MM-DD", nat, ca, oh, cin}, ...] sorted ascending, deduped by date.
const GAS_SERIES_KEY = "ww3dash.gasSeries.v1";
const gasSeries = {
  read() {
    try {
      const v = JSON.parse(localStorage.getItem(GAS_SERIES_KEY) || "[]");
      return Array.isArray(v) ? v : [];
    } catch { return []; }
  },
  // Upsert one or more dated rows in a single pass. Each row may set any
  // subset of {nat, ca, oh, cin}; existing fields on the same date are
  // preserved when not overridden.
  upsertRows(rows) {
    if (!Array.isArray(rows) || rows.length === 0) return;
    try {
      const cur = gasSeries.read();
      const byDate = new Map(cur.map(r => [r.date, r]));
      for (const r of rows) {
        if (!r || !r.date) continue;
        const prev = byDate.get(r.date) || { date: r.date };
        byDate.set(r.date, { ...prev, ...r });
      }
      const next = Array.from(byDate.values()).sort((a, b) => a.date.localeCompare(b.date));
      const trimmed = next.length > 400 ? next.slice(next.length - 400) : next;
      localStorage.setItem(GAS_SERIES_KEY, JSON.stringify(trimmed));
    } catch (_) {}
  },
  upsertToday(values) {
    gasSeries.upsertRows([{ date: new Date().toISOString().slice(0, 10), ...values }]);
  },
};

// Compute backdated YYYY-MM-DD strings from today, used to anchor AAA's
// Current/Yesterday/Week Ago/Month Ago/Year Ago ladder into the chart series.
function dateOffsetISO(daysAgo) {
  const d = new Date();
  d.setUTCHours(0, 0, 0, 0);
  d.setUTCDate(d.getUTCDate() - daysAgo);
  return d.toISOString().slice(0, 10);
}

// Round a numeric field to 2dp, or null if the source omitted it. Used so a missing
// 24h change renders as "—"/"→" instead of a fabricated +0.00% (no-synthetic-data).
const numOrNull = (x) => (Number.isFinite(x) ? +(+x).toFixed(2) : null);

// Render a small freshness label next to live prices. Cached values older than
// 30 min are surfaced as "stale" so users know the network is degraded.
function staleness(asOf) {
  if (!asOf) return { live: false, label: "—", stale: true };
  const ms = Date.now() - asOf;
  if (ms < 60_000)       return { live: true,  label: "live",          stale: false };
  if (ms < 300_000)      return { live: false, label: `${Math.round(ms/60000)}m ago`, stale: false };
  if (ms < 1_800_000)    return { live: false, label: `${Math.round(ms/60000)}m ago`, stale: false };
  if (ms < 86_400_000)   return { live: false, label: `${Math.round(ms/3_600_000)}h ago`, stale: true };
  return { live: false, label: "stale", stale: true };
}

// Yahoo Finance via CORS-proxy chain. Synthesises the legacy v7/quote shape from
// a BATCHED v8/spark call (all symbols in ONE request), falling back to per-symbol
// v8/chart only for whatever spark didn't return. v7/quote now needs a crumb cookie
// (401 via proxies), so it is not used.
//
// Why batched-first: the old code fired all six symbols as a simultaneous burst
// through the same free CORS proxy. The proxy (and Yahoo's per-IP limit) rate-limited
// under that load and intermittently dropped 2-3 symbols — NASDAQ/GOLD/BRENT were the
// usual casualties because only BRENT had any fallback. One spark request removes the
// burst; the per-symbol fill is throttled (<=2 in flight) and rotates its starting
// proxy so it can never recreate it. Every symbol now also falls through to Stooq and
// then a cached last-known-good, so a tile only goes blank if all three are down AND
// it has never loaded. All fallback values are real (live tick, real daily close, or a
// real prior fetch) — never synthetic.
const YF_SYMBOLS = ["^GSPC","^DJI","^IXIC","GC=F","CL=F","BZ=F"];
// Yahoo symbol -> dashboard tile key. Hoisted to module scope so the resilient fetch,
// cache, and ingest layers all map through one table instead of redefining it.
const YF_TILE = { "^GSPC":"SPX", "^DJI":"DOW", "^IXIC":"NDX", "GC=F":"GOLD", "CL=F":"WTI", "BZ=F":"BRENT" };
// Stooq equivalents (key-free CSV, permissive CORS so no proxy needed). Real daily
// closes — the no-proxy fallback that lets every tile survive a proxy outage.
const STOOQ_MAP = { "^GSPC":"^spx", "^DJI":"^dji", "^IXIC":"^ndq", "GC=F":"gc.f", "CL=F":"cl.f", "BZ=F":"cb.f" };
const YF_CHART = (s) => `https://query1.finance.yahoo.com/v8/finance/chart/${encodeURIComponent(s)}`;
const YF_SPARK = (syms) => `https://query1.finance.yahoo.com/v8/finance/spark?symbols=${syms.map(encodeURIComponent).join(",")}&range=1d&interval=5m`;
const YF_PROXIES = [
  (url) => "https://corsproxy.io/?" + encodeURIComponent(url),
  (url) => "https://api.allorigins.win/raw?url=" + encodeURIComponent(url),
  (url) => "https://api.codetabs.com/v1/proxy/?quest=" + encodeURIComponent(url),
];

// Concurrency-limited map — runs `fn` over items with at most `limit` in flight, so
// the per-symbol fallback can't re-create the all-at-once burst. A failing item
// resolves to null (the caller filters those out).
async function mapLimit(items, limit, fn) {
  const results = new Array(items.length);
  let next = 0;
  async function worker() {
    while (next < items.length) {
      const i = next++;
      try { results[i] = await fn(items[i], i); }
      catch (_) { results[i] = null; }
    }
  }
  await Promise.all(Array.from({ length: Math.min(limit, items.length) }, worker));
  return results;
}

// Single-URL fallback across the proxy chain. Each proxy gets one timed shot;
// returns the first success. `startAt` rotates which proxy is tried first so a set of
// per-symbol calls spreads its load across all three proxies instead of all starting
// on corsproxy.io. Replaces the old "all-or-nothing per proxy" pattern.
async function tryProxies(buildUrl, parse, timeout = FETCH_TIMEOUT_MS, startAt = 0) {
  let lastErr;
  const n = YF_PROXIES.length;
  for (let k = 0; k < n; k++) {
    const proxyMaker = YF_PROXIES[(startAt + k) % n];
    try {
      const r = await fetchWithTimeout(proxyMaker(buildUrl), timeout);
      if (!r.ok) { lastErr = new Error("status " + r.status); continue; }
      const parsed = await parse(r);
      if (parsed != null) return parsed;
      lastErr = new Error("parse returned null");
    } catch (e) { lastErr = e; }
  }
  throw lastErr || new Error("all proxies failed");
}

// Batched spark fetch — ALL symbols in one proxied request. Tolerates both spark
// response shapes (flat-keyed object, and the {spark:{result:[...]}} wrapper). Returns
// an array of legacy-shape quotes for whatever symbols it could read, else throws.
async function fetchYahooSpark() {
  return tryProxies(YF_SPARK(YF_SYMBOLS), async (r) => {
    const json = await r.json();
    const out = [];
    const add = (sym, price, prev) => {
      if (!sym || !(price > 0)) return;
      const chgPct = prev > 0 ? ((price - prev) / prev) * 100 : 0;
      out.push({ symbol: sym, regularMarketPrice: price, regularMarketChangePercent: chgPct });
    };
    if (json && json.spark && Array.isArray(json.spark.result)) {
      for (const res of json.spark.result) {
        const meta = res?.response?.[0]?.meta;
        if (meta) add(res.symbol, meta.regularMarketPrice, meta.chartPreviousClose ?? meta.previousClose);
      }
    } else if (json && typeof json === "object") {
      for (const sym of YF_SYMBOLS) {
        const res = json[sym];
        if (!res) continue;
        const closes = Array.isArray(res.close) ? res.close.filter(x => x != null) : [];
        const price = res.regularMarketPrice != null ? res.regularMarketPrice
                    : (closes.length ? closes[closes.length - 1] : null);
        add(sym, price, res.chartPreviousClose ?? res.previousClose);
      }
    }
    return out.length ? out : null;
  });
}

// Per-symbol Yahoo fetch with its own proxy fallback chain. `startAt` rotates the
// first proxy tried (see tryProxies). Used to fill any symbol spark didn't return.
async function fetchYahooSymbol(sym, startAt = 0) {
  return tryProxies(YF_CHART(sym), async (r) => {
    const json = await r.json();
    const meta = json?.chart?.result?.[0]?.meta;
    if (!meta || !(meta.regularMarketPrice > 0)) return null;
    const prev = meta.chartPreviousClose || meta.previousClose || meta.regularMarketPrice;
    const chgPct = prev > 0 ? ((meta.regularMarketPrice - prev) / prev) * 100 : 0;
    return {
      symbol: sym,
      regularMarketPrice: meta.regularMarketPrice,
      regularMarketChangePercent: chgPct,
    };
  }, FETCH_TIMEOUT_MS, startAt);
}

// Stooq fallback (no key, daily CSV, permissive CORS so no proxy needed). A real
// last-close for any mapped symbol — slightly less fresh than Yahoo's live tick but
// never synthetic. Generalises the old Brent-only helper to every instrument.
async function fetchStooq(sym) {
  const ss = STOOQ_MAP[sym];
  if (!ss) throw new Error("stooq: no mapping for " + sym);
  const url = `https://stooq.com/q/l/?s=${encodeURIComponent(ss)}&f=sd2t2ohlcv&h&e=csv`;
  const r = await fetchWithTimeout(url, FETCH_TIMEOUT_MS);
  if (!r.ok) throw new Error("stooq " + r.status);
  const text = await r.text();
  // CSV header line + one data line. Columns: Symbol,Date,Time,Open,High,Low,Close,Volume
  const lines = text.trim().split(/\r?\n/);
  if (lines.length < 2) throw new Error("stooq no data");
  const cols = lines[1].split(",");
  const open = parseFloat(cols[3]);
  const close = parseFloat(cols[6]);
  if (!(close > 0)) throw new Error("stooq invalid close");
  const chgPct = open > 0 ? ((close - open) / open) * 100 : 0;
  return { symbol: sym, regularMarketPrice: close, regularMarketChangePercent: chgPct };
}

// Resilient single-symbol fetch: Yahoo (proxy chain) -> Stooq -> localStorage
// last-known-good. The cache value carries `_fromCache` (+ `_asOf`) so the UI keeps
// its real age and can flag it stale. Every tier is real data — no synthetic fallback.
async function fetchSymbolResilient(sym, startAt = 0) {
  try { return await fetchYahooSymbol(sym, startAt); } catch (_) {}
  try { return await fetchStooq(sym); }                catch (_) {}
  const tile = YF_TILE[sym];
  const c = tile ? priceCache.read()[tile] : null;
  if (c && c.price != null) {
    return { symbol: sym, regularMarketPrice: c.price, regularMarketChangePercent: c.chg ?? 0, _fromCache: true, _asOf: c.asOf };
  }
  throw new Error(sym + ": all sources failed (Yahoo+Stooq+cache empty)");
}

async function fetchYahooMarkets() {
  // One batched spark request first — removes the six-way proxy burst that was
  // dropping NASDAQ/GOLD/BRENT. Then fill only what spark missed, throttled and
  // proxy-rotated so the fill can't recreate the burst; each filled symbol still
  // falls through Yahoo -> Stooq -> cache.
  const collected = new Map();
  try {
    for (const q of await fetchYahooSpark()) collected.set(q.symbol, q);
  } catch (_) { /* spark unavailable — the per-symbol fill below covers every symbol */ }

  const missing = YF_SYMBOLS.filter(s => !collected.has(s));
  if (missing.length) {
    const filled = await mapLimit(missing, 2, (s, i) => fetchSymbolResilient(s, i));
    for (const q of filled) if (q) collected.set(q.symbol, q);
  }

  const ok = Array.from(collected.values());
  if (ok.length === 0) throw new Error("All market symbols failed");
  return { quoteResponse: { result: ok } };
}

// AAA Fuel Prices via CORS proxy chain. AAA's gasprices.aaa.com pages embed
// both a headline current price and a 5-row historical ladder
//   Current Avg. / Yesterday Avg. / Week Ago Avg. / Month Ago Avg. / Year Ago Avg.
// We scrape both: the headline goes to the live tiles, and the ladder is
// translated into back-dated points on the gas-price-history chart so Ohio
// and Cincinnati get visible curves from day one instead of a single dot.
// All values are real AAA data — no synthesis.
const AAA_HOST = "https://gasprices.aaa.com";
function extractAaaPrice(html) {
  // AAA renders a curly apostrophe ("Today’s AAA National Average $4.0600")
  // and up to 4 decimals — tolerate both or the headline never matches and we
  // silently fall through to the loose first-dollar match.
  const m = html.match(/Today['’]?s\s+AAA[^$]*\$([1-9]\.\d{2,4})/i);
  if (m) return parseFloat(m[1]);
  const all = html.match(/\$([1-9]\.\d{2,3})\b/g);
  if (all && all.length > 0) return parseFloat(all[0].slice(1));
  return null;
}
// Pull the 5-value ladder out of the first ladder table that appears after
// `anchorRegex`. AAA renders ladders as a sequence of
//   <td>Current Avg.</td>  <td>$X.XXX</td>
//   <td>Yesterday Avg.</td><td>$X.XXX</td>
//   …
// The first `$X.XXX` after each `Avg.</td>` is the regular-grade price, which
// is the only grade we plot.
function extractAaaLadderAfter(html, anchorRegex) {
  const m = anchorRegex.exec(html);
  if (!m) return null;
  const start = m.index + m[0].length;
  const slice = html.slice(start, start + 6000);
  const re = /Avg\.<\/td>\s*<td>\s*\$([1-9]\.\d{2,3})/gi;
  const labels = ["current", "yesterday", "weekAgo", "monthAgo", "yearAgo"];
  const out = {};
  let mm, i = 0;
  while ((mm = re.exec(slice)) !== null && i < labels.length) {
    out[labels[i++]] = parseFloat(mm[1]);
  }
  return Object.keys(out).length > 0 ? out : null;
}
function extractAaaNationalLadder(html) {
  return extractAaaLadderAfter(html, /(?=Current Avg)/);
}
// Diesel shares the regular-grade ladder table (columns: Regular / Mid-Grade /
// Premium / Diesel [/ E85]). The Diesel column is located by its <th> header,
// not a hardcoded position, so a column reorder can never silently turn E85 or
// Premium into "diesel". A row whose cell count doesn't match the header count
// (an empty cell would shift the columns) is skipped rather than misread.
// Returns {current, yesterday, weekAgo, monthAgo, yearAgo} or null. Mirrors
// scripts/update-markets.js.
function extractAaaNationalDiesel(html) {
  const m = /(?=Current Avg)/.exec(html);
  if (!m) return null;
  const tableStart = html.lastIndexOf("<table", m.index);
  if (tableStart < 0) return null;
  const heads = [...html.slice(tableStart, m.index).matchAll(/<th[^>]*>([\s\S]*?)<\/th>/gi)]
    .map(h => h[1].replace(/<[^>]*>/g, "").trim());
  const col = heads.findIndex(t => /^diesel$/i.test(t)) - 1; // heads[0] is the blank row-label column
  if (col < 0) return null;
  const keys = { "current":"current", "yesterday":"yesterday", "week ago":"weekAgo", "month ago":"monthAgo", "year ago":"yearAgo" };
  const rowRe = /<td>\s*(Current|Yesterday|Week Ago|Month Ago|Year Ago)\s+Avg\.\s*<\/td>([\s\S]*?)<\/tr>/gi;
  const slice = html.slice(tableStart, tableStart + 8000);
  const out = {};
  let rm;
  while ((rm = rowRe.exec(slice)) !== null) {
    const prices = [...rm[2].matchAll(/\$(\d{1,2}\.\d{2,4})/g)].map(p => parseFloat(p[1]));
    if (prices.length !== heads.length - 1) continue;
    const v = prices[col];
    if (v > 1 && v < 20) out[keys[rm[1].toLowerCase()]] = +v.toFixed(3);
  }
  return Object.keys(out).length > 0 ? out : null;
}
function extractAaaStateLadder(html, stateName) {
  return extractAaaLadderAfter(html, new RegExp(stateName + "[\\s\\S]{0,80}average gas prices", "i"));
}
function extractAaaMetroLadder(html, metro) {
  // Metro headings like "Cincinnati (OH only)</h3>" — match the metro name
  // then scan forward to the ladder table.
  return extractAaaLadderAfter(html, new RegExp(metro, "i"));
}

// Parse one AAA page → { price, ladder }. Ladder is best-effort and may be
// null if the page format ever changes.
async function fetchAaaRegion(path, parseLadder, parseDiesel) {
  return tryProxies(AAA_HOST + path, async (r) => {
    const html = await r.text();
    // Prefer the region's anchored ladder "Current Avg." — the loose headline
    // regex can catch the NATIONAL banner AAA puts on every page (state pages
    // included), which is the wrong number for a state fetch.
    const ladder = parseLadder ? parseLadder(html) : null;
    const price = (ladder && ladder.current != null) ? ladder.current : extractAaaPrice(html);
    if (price == null) return null;
    // Diesel rides the same page; a missing Diesel column must not fail the
    // regular-gas fetch, so it is optional and null on any parse miss.
    let diesel = null;
    try { diesel = parseDiesel ? parseDiesel(html) : null; } catch (_) {}
    return { price, ladder, diesel };
  });
}

async function fetchAaaCincinnatiRegion() {
  // The Cincinnati price + ladder live on the Ohio state page. AAA does not
  // serve a stable per-city URL (?city=… returns the national homepage).
  try {
    return await tryProxies(AAA_HOST + "/?state=OH", async (r) => {
      const html = await r.text();
      const ladder = extractAaaMetroLadder(html, "Cincinnati");
      const price = ladder?.current ?? null;
      if (price == null) return null;
      return { price, ladder };
    });
  } catch (_) {}
  return null;
}

async function fetchAaaGas() {
  // Four independent fallback chains in parallel. Settles partial results so a
  // single dead region (e.g. Cincinnati metro) doesn't void the others.
  const [nat, ca, oh, cin] = await Promise.allSettled([
    fetchAaaRegion("/",           html => extractAaaNationalLadder(html), html => extractAaaNationalDiesel(html)),
    fetchAaaRegion("/?state=CA",  html => extractAaaStateLadder(html, "California")),
    fetchAaaRegion("/?state=OH",  html => extractAaaStateLadder(html, "Ohio")),
    fetchAaaCincinnatiRegion(),
  ]);
  const unpack = (r) => r.status === "fulfilled" && r.value ? r.value : null;
  const out = {
    national:   unpack(nat),
    california: unpack(ca),
    ohio:       unpack(oh),
    cincinnati: unpack(cin),
  };
  if (!out.national && !out.california && !out.ohio && !out.cincinnati) {
    throw new Error("All AAA regions failed");
  }
  return out;
}

// Translate each region's ladder into back-dated chart rows. AAA's ladder
// gives Current (today), Yesterday (-1), Week Ago (-7), Month Ago (-30),
// Year Ago (-365) — real AAA historical snapshots, not synthesis.
function aaaLadderToRows(ladder, fieldName) {
  if (!ladder) return [];
  const offsets = { current: 0, yesterday: 1, weekAgo: 7, monthAgo: 30, yearAgo: 365 };
  const rows = [];
  for (const [k, v] of Object.entries(ladder)) {
    if (v == null || !isFinite(v)) continue;
    const off = offsets[k];
    if (off == null) continue;
    rows.push({ date: dateOffsetISO(off), [fieldName]: v });
  }
  return rows;
}

// GDELT's free endpoint rate-limits aggressively (HTTP 429). Retry on 429/5xx
// with backoff and reject with a structured {kind, status?} so the caller can
// render a specific label like "Failed: News (rate-limited)".
//
// Query uses OR-linked terms so any single topic returns results even on a quiet
// day. maxrecords=25 gives the severity filter room to select 10–20 headlines.
// Simple + encoding (no encodeURIComponent) keeps the URL readable and avoids
// double-encoding issues that cause GDELT to return an HTML error page.
// GDELT requires OR terms to be wrapped in parentheses (%28 / %29).
const GDELT_URL = "https://api.gdeltproject.org/api/v2/doc/doc?query=%28Iran+OR+Hormuz+OR+nuclear+OR+ceasefire+OR+Tehran+OR+sanctions%29&mode=artlist&maxrecords=25&timespan=24h&format=json";

// How many live headlines to surface in the feed.
// Scales with WW3% so a hot news day shows more context: ≥65% → 18, ≥50% → 15, ≥35% → 12, <35% → 10.
// Always clamped to [10, 20].
function newsCountForSeverity(ww3pct) {
  if (ww3pct >= 65) return 18;
  if (ww3pct >= 50) return 15;
  if (ww3pct >= 35) return 12;
  return 10;
}

// Remove duplicate stories where the same headline appears from multiple outlets.
// Uses the first 7 significant words (stripped of punctuation) as the dedup key.
function dedupeByTitle(articles) {
  const seen = new Set();
  return articles.filter(a => {
    if (!a.title) return false;
    const key = a.title
      .toLowerCase()
      .replace(/[^a-z0-9 ]/g, " ")
      .replace(/\s+/g, " ")
      .trim()
      .split(" ")
      .slice(0, 7)
      .join(" ");
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}
async function fetchGdeltNews() {
  const delays = [0, 800, 2000];
  let lastReason = { kind: "network" };
  for (const delay of delays) {
    if (delay) await new Promise(r => setTimeout(r, delay));
    let resp;
    try { resp = await fetch(GDELT_URL); }
    catch (_) { lastReason = { kind: "network" }; continue; }
    if (resp.ok) {
      try { return await resp.json(); }
      catch (_) { throw { kind: "parse" }; }
    }
    if (resp.status === 429 || resp.status >= 500) {
      lastReason = resp.status === 429
        ? { kind: "ratelimit", status: 429 }
        : { kind: "http", status: resp.status };
      continue;
    }
    throw { kind: "http", status: resp.status };
  }
  throw lastReason;
}

async function fetchUpdate(setMkt, setGas, setWw3, setThemes, setBreaking, setNews, setRefreshing, setRefreshCount, setRefreshErr, setLastUpdate, setSourceStatus) {
  setRefreshing(true);
  setRefreshErr(null);
  if (setSourceStatus) setSourceStatus(s => ({ ...s, crypto:"loading", markets:"loading", news:"loading", gas:"loading" }));

  // Run all free sources in parallel — each fails independently
  const [cgRes, yfRes, aaaRes, gdRes] = await Promise.allSettled([
    // 1. CoinGecko — BTC + ETH (free, no key, CORS enabled). Timeout via AbortController
    //    so a stalled CoinGecko request can't hold the whole pipeline open.
    fetchWithTimeout("https://api.coingecko.com/api/v3/simple/price?ids=bitcoin,ethereum&vs_currencies=usd&include_24hr_change=true")
      .then(r => r.ok ? r.json() : Promise.reject("CoinGecko " + r.status)),

    // 2. Yahoo Finance via proxy chain — SPX, DOW, NASDAQ, GOLD, WTI, BRENT
    fetchYahooMarkets(),

    // 3. AAA via proxy chain — national + CA + OH gas averages
    fetchAaaGas(),

    // 4. GDELT — Iran/Middle East news (free, no key, CORS enabled). Retries on 429/5xx.
    fetchGdeltNews(),
  ]);

  let updateCount = 0;
  const errors = [];

  // ── Crypto ─────────────────────────────────────────────────────────────────
  let cryptoOK = false;
  if (cgRes.status === "fulfilled") {
    const cg = cgRes.value;
    const btc = cg?.bitcoin?.usd, eth = cg?.ethereum?.usd;
    // Require a real numeric price before marking the tile live — a malformed-but-200
    // body (e.g. {bitcoin:{},ethereum:{}}) must stay a skeleton, not show "—" as live.
    if (Number.isFinite(btc) && Number.isFinite(eth)) {
      setMkt(prev => ({
        ...prev,
        BTC: { price: btc, chg: numOrNull(cg.bitcoin.usd_24h_change),  loaded: true },
        ETH: { price: eth, chg: numOrNull(cg.ethereum.usd_24h_change), loaded: true },
      }));
      updateCount++; cryptoOK = true;
    }
  }
  if (!cryptoOK) errors.push("Crypto");

  // ── Stocks / Commodities ───────────────────────────────────────────────────
  let marketsOK = false;
  if (yfRes.status === "fulfilled") {
    const quotes = yfRes.value?.quoteResponse?.result || [];
    // Only quotes we can map to a tile with a usable price count as ingest. Gating on
    // this (not raw quotes.length) keeps the refresh timestamp + "Updated" label honest.
    const valid = quotes.filter(q => YF_TILE[q.symbol] && q.regularMarketPrice > 0);
    if (valid.length > 0) {
      const now = Date.now();
      // Persist every freshly-fetched symbol as last-known-good (computed synchronously
      // so it doesn't depend on React flushing setMkt first). Cache-sourced quotes
      // (_fromCache) are skipped so their original asOf isn't bumped — re-stamping a
      // stale value would make it look fresh.
      const cachePatch = {};
      for (const q of valid) {
        if (q._fromCache) continue;
        cachePatch[YF_TILE[q.symbol]] = {
          price: q.regularMarketPrice,
          chg:   numOrNull(q.regularMarketChangePercent),
          asOf:  now,
        };
      }
      if (Object.keys(cachePatch).length) priceCache.write(cachePatch);
      setMkt(prev => {
        const n = { ...prev };
        for (const q of valid) {
          n[YF_TILE[q.symbol]] = {
            price: q.regularMarketPrice,
            chg: numOrNull(q.regularMarketChangePercent),
            loaded: true,
            asOf: q._fromCache ? (q._asOf ?? now) : now,
            fromCache: !!q._fromCache,
          };
        }
        return n;
      });
      updateCount++; marketsOK = true;
    }
  }
  if (!marketsOK) errors.push("Markets");

  // ── Gas (AAA) ──────────────────────────────────────────────────────────────
  // Per-URL fallback in fetchAaaGas means partial success is the norm. Each
  // region returns { price, ladder } — the headline `price` drives the live
  // tiles, and the 5-point `ladder` (Current/Yesterday/WeekAgo/MonthAgo/YearAgo)
  // is translated into back-dated chart rows so Ohio + Cincinnati get visible
  // historical curves instead of a single dot. All ladder values are real AAA
  // snapshots, not synthesis.
  let gasOK = false;
  if (aaaRes.status === "fulfilled" && aaaRes.value) {
    const a = aaaRes.value;
    const now = Date.now();
    const price = (region) => region?.price ?? null;
    // National diesel: a ladder object {current, yesterday, weekAgo, monthAgo,
    // yearAgo} straight from AAA's national table, or null on a parse miss.
    const dieselLadder = a.national?.diesel ?? null;
    const prices = {
      national:   price(a.national),
      california: price(a.california),
      ohio:       price(a.ohio),
      cincinnati: price(a.cincinnati),
      diesel:     dieselLadder?.current ?? null,
    };
    setGas(prev => ({
      ...prev,
      national:   prices.national   ?? prev.national,
      california: prices.california ?? prev.california,
      ohio:       prices.ohio       ?? prev.ohio,
      cincinnati: prices.cincinnati ?? prev.cincinnati,
      diesel:       prices.diesel ?? prev.diesel,
      dieselLadder: dieselLadder  ?? prev.dieselLadder,
      asOf:       now,
      loaded:     true,
      fromCache:  false, // a live fetch just landed — clear the cache-hydrate flag
    }));
    priceCache.write({ gas: { ...prices, dieselLadder, asOf: now } });
    // Build the series rows: today's tip (all 4) plus every ladder point for
    // every region that returned one. gasSeries.upsertRows deduplicates by
    // date and merges fields, so multiple regions hitting the same backdate
    // (e.g. all four "Week Ago") collapse into one row.
    const rows = [];
    const today = dateOffsetISO(0);
    const todayRow = { date: today };
    if (prices.national   != null) todayRow.nat = prices.national;
    if (prices.california != null) todayRow.ca  = prices.california;
    if (prices.ohio       != null) todayRow.oh  = prices.ohio;
    if (prices.cincinnati != null) todayRow.cin = prices.cincinnati;
    if (prices.diesel     != null) todayRow.dsl = prices.diesel;
    if (Object.keys(todayRow).length > 1) rows.push(todayRow);
    rows.push(...aaaLadderToRows(a.national?.ladder,   "nat"));
    rows.push(...aaaLadderToRows(dieselLadder,         "dsl"));
    rows.push(...aaaLadderToRows(a.california?.ladder, "ca"));
    rows.push(...aaaLadderToRows(a.ohio?.ladder,       "oh"));
    rows.push(...aaaLadderToRows(a.cincinnati?.ladder, "cin"));
    if (rows.length > 0) gasSeries.upsertRows(rows);
    if (prices.national != null) { updateCount++; gasOK = true; }
  }
  if (!gasOK) errors.push("Gas");

  // ── News ───────────────────────────────────────────────────────────────────
  let newsOK = false;
  let newsErrReason = null;
  if (gdRes.status === "fulfilled") {
    // GDELT uses "English" or "en" depending on version — accept both
    const articles = (gdRes.value?.articles || []).filter(a => a.title && (!a.language || a.language.toLowerCase().startsWith("en")));
    if (articles.length > 0) {
      // Deduplicate first so the same story from 4 outlets counts once, then take top N.
      const unique = dedupeByTitle(articles);
      const newsItems = unique.slice(0, newsCountForSeverity(WW3_PCT)).map(a => {
        let timeStr = "--:--";
        try {
          const d = String(a.seendate || "");
          // GDELT seendate formats: "20260413" or "20260413T120000Z"
          const iso = d.length >= 15
            ? `${d.slice(0,4)}-${d.slice(4,6)}-${d.slice(6,8)}T${d.slice(9,11)}:${d.slice(11,13)}:00Z`
            : `${d.slice(0,4)}-${d.slice(4,6)}-${d.slice(6,8)}`;
          const dt = new Date(iso);
          if (!isNaN(dt)) timeStr = dt.toLocaleTimeString("en-US", { hour:"2-digit", minute:"2-digit" });
        } catch(_) {}
        return {
          t: timeStr,
          s: (a.domain || "NEWS").replace(/^www\./, "").split(".")[0].toUpperCase().slice(0, 10),
          h: a.title,
          u: a.url || null,
        };
      });
      setNews(newsItems);
      setBreaking(newsItems.slice(0, 4).map(n => n.h.toUpperCase()));
      updateCount++; newsOK = true;
    } else {
      newsErrReason = "no articles";
    }
  } else {
    const reason = gdRes.reason || {};
    if (reason.kind === "ratelimit")    newsErrReason = "rate-limited";
    else if (reason.kind === "http")    newsErrReason = `API ${reason.status || "error"}`;
    else if (reason.kind === "parse")   newsErrReason = "parse error";
    else                                newsErrReason = "network";
  }
  if (!newsOK) errors.push(newsErrReason ? `News (${newsErrReason})` : "News");

  if (setSourceStatus) {
    setSourceStatus({
      crypto:  cryptoOK  ? "ok" : "fail",
      markets: marketsOK ? "ok" : "fail",
      gas:     gasOK     ? "ok" : "fail",
      news:    newsOK    ? "ok" : "fail",
    });
  }

  // ── Finalise ───────────────────────────────────────────────────────────────
  // Derive the "Updated" list from the same OK flags that gate ingest, so the refresh
  // timestamp and label can never disagree with what was actually written to state.
  const sources = [];
  if (cryptoOK)  sources.push("Crypto");
  if (marketsOK) sources.push("Markets");
  if (gasOK)     sources.push("Gas");
  if (newsOK)    sources.push("News");

  if (sources.length > 0) {
    setRefreshCount(c => c + 1);
    setLastUpdate(
      new Date().toLocaleDateString("en-US", { month:"2-digit", day:"2-digit", year:"numeric" }) +
      " · " + new Date().toLocaleTimeString("en-US", { hour:"2-digit", minute:"2-digit", timeZoneName:"short" })
    );
    setRefreshErr(
      errors.length > 0
        ? `Updated: ${sources.join(", ")} · Failed: ${errors.join(", ")}`
        : null
    );
  } else {
    setRefreshErr("All sources failed — check internet connection");
  }
  setRefreshing(false);
}

// ─── Briefing Mode (Presenter view) ───────────────────────────────────────
// Press B to enter; arrow keys to navigate; Esc to exit. 8 slides, full-bleed.
function BriefingMode({ active, onClose, ww3, mkt, gas, conflictDay }) {
  const [slide, setSlide] = useState(0);
  const dlgRef = useRef(null);
  const lastFocus = useRef(null);
  const ww3Color = ww3 > 60 ? DANGER : ww3 > 40 ? AMBER : GREEN;
  const currentRung = ESCALATION_LADDER.find(r => r.pct === Math.floor(ww3 / 10) * 10) || ESCALATION_LADDER[ESCALATION_LADDER.length - 1];
  const theaters = THEATERS_DATA
    .filter(t => ["China","Taiwan","Iran","Lebanon","Ukraine"].includes(t.name))
    .map(t => ({ flag:t.flag, name:t.name, threat:t.threat, color:t.color || TEXT_MID, note:t.status }));
  const recentEvents = [...TIMELINE].slice(-14).reverse();
  const topPlayers = CHESS_PLAYERS.slice(0, 6);
  const scenarioCard = AI_CARDS[3]; // STRATEGIC OUTLOOK

  // Track invocation focus so we can restore on close.
  useEffect(() => {
    if (active) {
      lastFocus.current = document.activeElement;
      setSlide(0);
      requestAnimationFrame(() => dlgRef.current?.focus());
    } else if (lastFocus.current) {
      try { lastFocus.current.focus(); } catch (_) {}
    }
  }, [active]);

  // Keyboard navigation
  useEffect(() => {
    if (!active) return;
    const onKey = (e) => {
      if (e.key === "Escape") { e.preventDefault(); onClose(); return; }
      if (e.key === "ArrowRight" || e.key === " " || e.key === "PageDown") { e.preventDefault(); setSlide(s => Math.min(7, s + 1)); }
      else if (e.key === "ArrowLeft" || e.key === "PageUp") { e.preventDefault(); setSlide(s => Math.max(0, s - 1)); }
      else if (e.key === "Home") { e.preventDefault(); setSlide(0); }
      else if (e.key === "End")  { e.preventDefault(); setSlide(7); }
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [active, onClose]);

  if (!active) return null;

  const slides = [
    // 1. Lead
    () => (
      <div style={{ maxWidth:920, width:"100%" }}>
        <div style={{ display:"flex", alignItems:"center", gap:12, marginBottom:18 }}>
          <span style={{ width:9, height:9, borderRadius:"50%", background:IRAN, animation:"ping 1.6s ease infinite" }} />
          <M style={{ fontSize:12, color:IRAN, letterSpacing:".22em", fontWeight:700, textTransform:"uppercase" }}>Lead Development</M>
          <span style={{ width:1, height:14, background:RAISE_3 }} />
          <M style={{ fontSize:12, color:TEXT_DIM, letterSpacing:".06em", fontVariantNumeric:"tabular-nums" }}>{BASE_LAST_UPDATE} · Day {conflictDay}</M>
        </div>
        <div className="display" style={{ fontSize:46, fontWeight:600, color:TEXT_HI, lineHeight:1.12, letterSpacing:"-.022em", marginBottom:24, fontVariationSettings:"'opsz' 46" }}>
          {LEAD_TLDR.title}
        </div>
        <div style={{ fontSize:18, color:TEXT_BODY, lineHeight:1.6, marginBottom:32, fontWeight:450 }}>
          {LEAD_TLDR.summary}
        </div>
        <div style={{ display:"grid", gridTemplateColumns:"repeat(3, 1fr)", gap:14 }}>
          {LEAD_TLDR.facts.map((f, i) => {
            const isPrimary = i === 0;
            return (
              <div key={f.l} style={{ padding:"18px 20px", background: isPrimary ? `linear-gradient(135deg, ${alpha(DANGER, .08)}, transparent 70%)` : RAISE_1, border:`1px solid ${isPrimary ? alpha(DANGER, .32) : BORDER}`, borderRadius:14 }}>
                <Eyebrow mb={8} color={isPrimary ? DANGER : TEXT_DIM}>{f.l}</Eyebrow>
                <M style={{ fontSize:14.5, color: isPrimary ? DANGER : TEXT_HI, fontWeight:600, fontVariantNumeric:"tabular-nums", letterSpacing:"-.01em", lineHeight:1.5 }}>
                  {f.v}
                </M>
              </div>
            );
          })}
        </div>
      </div>
    ),
    // 2. WW3 + Ladder
    () => {
      // Show a 5-rung window centred on the current rung (±2, clamped).
      const currentIdx = ESCALATION_LADDER.findIndex(r => r.pct === Math.floor(ww3 / 10) * 10);
      const ci = currentIdx < 0 ? ESCALATION_LADDER.length - 1 : currentIdx;
      const lo = Math.max(0, ci - 2);
      const hi = Math.min(ESCALATION_LADDER.length - 1, lo + 4);
      const visibleRungs = ESCALATION_LADDER.slice(lo, hi + 1);
      return (
        <div style={{ maxWidth:1040, width:"100%" }}>
          <Eyebrow mb={12} color={TEXT_MID}>WW3 Probability · Escalation Ladder</Eyebrow>
          <div style={{ display:"grid", gridTemplateColumns:"auto 1fr", gap:36, alignItems:"center" }}>
            <div>
              <div className="display" style={{ fontSize:180, fontWeight:600, color:ww3Color, lineHeight:.9, letterSpacing:"-.05em", fontVariantNumeric:"tabular-nums", fontVariationSettings:"'opsz' 96" }}>
                <TickingNumber value={ww3} duration={1100} /><span style={{ fontSize:64, opacity:.55 }}>%</span>
              </div>
              <div style={{ marginTop:14, display:"flex", alignItems:"center", gap:10 }}>
                <span style={{ fontFamily:SANS, fontSize:12, fontWeight:600, letterSpacing:".10em", color:ww3Color, padding:"4px 11px", borderRadius:999, background:alpha(ww3Color, .09), border:`1px solid ${alpha(ww3Color, .23)}` }}>Rung {currentRung.pct} · {currentRung.label}</span>
              </div>
              <div style={{ marginTop:18 }}>
                <div style={{ maxWidth:340 }}>
                  <EventSeriesChart series={WW3_SERIES} variant="mini" height={64} color={ww3Color}
                    yMin={0} yMax={70} format={(v) => `${Math.round(v)}`} unit="%" />
                </div>
              </div>
            </div>
            <div style={{ display:"flex", flexDirection:"column", gap:4 }}>
              {lo > 0 && <div style={{ fontSize:11, color:TEXT_DIM, padding:"2px 12px", letterSpacing:".06em" }}>▲ {lo} rung{lo > 1 ? "s" : ""} above</div>}
              {visibleRungs.map(rung => {
                const current = rung.pct === Math.floor(ww3 / 10) * 10;
                const passed = rung.pct < Math.floor(ww3 / 10) * 10;
                const labelColor = passed ? DANGER : current ? AMBER : TEXT_MID;
                return (
                  <div key={rung.pct} className={current ? "glow-rung" : ""} style={{ display:"flex", alignItems:"center", gap:12, padding:"9px 14px", borderRadius:8, background: current ? alpha(AMBER, .12) : passed ? alpha(DANGER, .04) : "transparent", border:`1px solid ${current ? alpha(AMBER, .36) : passed ? alpha(DANGER, .10) : "transparent"}` }}>
                    <M style={{ fontSize:14, fontWeight:700, color:labelColor, width:44, flexShrink:0, fontVariantNumeric:"tabular-nums" }}>{rung.pct}%</M>
                    <span style={{ fontSize:14, fontWeight:600, color:labelColor, flex:1 }}>{rung.label}</span>
                    {current && <M style={{ fontSize:FS.xs, fontWeight:600, color:AMBER, letterSpacing:".12em", padding:"2px 8px", borderRadius:999, background:alpha(AMBER, .18), border:`1px solid ${alpha(AMBER, .40)}`, flexShrink:0 }}>NOW</M>}
                  </div>
                );
              })}
              {hi < ESCALATION_LADDER.length - 1 && <div style={{ fontSize:11, color:TEXT_DIM, padding:"2px 12px", letterSpacing:".06em" }}>▼ {ESCALATION_LADDER.length - 1 - hi} rung{ESCALATION_LADDER.length - 1 - hi > 1 ? "s" : ""} below</div>}
            </div>
          </div>
        </div>
      );
    },
    // 3. Active theaters
    () => (
      <div style={{ maxWidth:1040, width:"100%" }}>
        <Eyebrow mb={14} color={TEXT_MID}>Active Theaters · Day {conflictDay}</Eyebrow>
        <div className="display" style={{ fontSize:30, fontWeight:600, color:TEXT_HI, marginBottom:24, letterSpacing:"-.015em", fontVariationSettings:"'opsz' 30" }}>
          {theaters.length} active theaters · WW3 at <span style={{ color:ww3Color }}>{ww3}%</span>
        </div>
        <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:14 }}>
          {theaters.map(t => (
            <div key={t.name} style={{ padding:"18px 22px", borderRadius:14, background:RAISE_1, borderLeft:`4px solid ${t.color}`, border:`1px solid ${BORDER}` }}>
              <div style={{ display:"flex", alignItems:"center", gap:14, marginBottom:8 }}>
                <span style={{ fontSize:32, lineHeight:1 }}>{t.flag}</span>
                <span className="display" style={{ fontSize:22, fontWeight:600, color:TEXT_HI, letterSpacing:"-.01em" }}>{t.name}</span>
                <div style={{ flex:1 }} />
                <M style={{ fontSize:18, fontWeight:600, color:t.color, fontVariantNumeric:"tabular-nums" }}>{t.threat}%</M>
              </div>
              <div style={{ fontSize:13.5, color:TEXT_BODY, lineHeight:1.55 }}>{t.note}</div>
            </div>
          ))}
        </div>
      </div>
    ),
    // 4. Key Developments
    () => (
      <div style={{ maxWidth:980, width:"100%" }}>
        <Eyebrow mb={14} color={AMBER}>Key Developments · Today</Eyebrow>
        <div className="display" style={{ fontSize:26, fontWeight:600, color:TEXT_HI, marginBottom:24, letterSpacing:"-.012em", fontVariationSettings:"'opsz' 26" }}>What changed in the last 24 hours</div>
        <div style={{ display:"flex", flexDirection:"column", gap:14 }}>
          {KEY_DEVS.slice(0, 6).map((d, i) => (
            <div key={i} style={{ display:"flex", gap:18, padding:"14px 20px", background:alpha(AMBER, .05), border:`1px solid ${alpha(AMBER, .18)}`, borderRadius:12 }}>
              <M style={{ fontSize:12, fontWeight:700, color:AMBER, letterSpacing:".10em", flexShrink:0, width:22, paddingTop:2 }}>{String(i+1).padStart(2,"0")}</M>
              <div style={{ fontSize:15.5, color:TEXT_HI, lineHeight:1.55, fontWeight:450 }}>{d}</div>
            </div>
          ))}
        </div>
      </div>
    ),
    // 5. Timeline — last 14 days
    () => (
      <div style={{ maxWidth:1020, width:"100%" }}>
        <Eyebrow mb={14} color={TEXT_MID}>Timeline · Last 14 Days</Eyebrow>
        <div style={{ position:"relative", maxHeight:"66vh", overflowY:"auto", paddingRight:8 }}>
          <div style={{ position:"absolute", left:74, top:6, bottom:6, width:1, background:`linear-gradient(180deg, ${alpha(DANGER, .33)}, ${alpha(AMBER, .33)}, ${BORDER})` }} />
          {recentEvents.map((ev, i) => {
            const col = ({ extreme:DANGER, critical:CRITICAL, high:AMBER })[ev.sev] || TEXT_MID;
            return (
              <div key={i} style={{ display:"flex", gap:16, padding:"10px 0", alignItems:"flex-start" }}>
                <M style={{ fontSize:12, color:TEXT_DIM, width:62, flexShrink:0, paddingTop:4, textAlign:"right", fontWeight:500, fontVariantNumeric:"tabular-nums" }}>{ev.date}</M>
                <div style={{ width:10, height:10, borderRadius:"50%", background:col, flexShrink:0, marginTop:7, boxShadow:`0 0 0 3px var(--bg), 0 0 12px ${alpha(col, .53)}` }} />
                <div style={{ flex:1, fontSize:14, color:TEXT_BODY, lineHeight:1.6 }}>{ev.desc}</div>
              </div>
            );
          })}
        </div>
      </div>
    ),
    // 6. Chessboard
    () => (
      <div style={{ maxWidth:1020, width:"100%" }}>
        <Eyebrow mb={14} color={TEXT_MID}>Geopolitical Chessboard · Top 6 Players</Eyebrow>
        <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:14 }}>
          {topPlayers.map(p => (
            <div key={p.name} style={{ padding:"16px 20px", borderRadius:14, background:RAISE_1, borderLeft:`4px solid ${p.color}`, border:`1px solid ${BORDER}` }}>
              <div style={{ display:"flex", alignItems:"center", gap:12, marginBottom:10 }}>
                <span style={{ fontSize:24, lineHeight:1 }}>{p.flag}</span>
                <span className="display" style={{ fontSize:17, fontWeight:600, color:TEXT_HI, letterSpacing:"-.01em" }}>{p.name}</span>
              </div>
              <Eyebrow mb={4} color={p.color}>Move</Eyebrow>
              <div style={{ fontSize:13, color:TEXT_BODY, lineHeight:1.55 }}>{p.move}</div>
            </div>
          ))}
        </div>
      </div>
    ),
    // 7. Markets
    () => (
      <div style={{ maxWidth:960, width:"100%" }}>
        <Eyebrow mb={14} color={TEXT_MID}>Markets · Live Snapshot</Eyebrow>
        <div style={{ display:"grid", gridTemplateColumns:"repeat(4, 1fr)", gap:14, marginBottom:18 }}>
          {[
            { l:"S&P 500", v: mkt.SPX.price   != null ? fmt.num(Math.round(mkt.SPX.price))           : null, c:mkt.SPX.chg },
            { l:"BRENT",   v: mkt.BRENT.price != null ? fmt.money(mkt.BRENT.price)                    : null, c:mkt.BRENT.chg },
            { l:"GOLD",    v: mkt.GOLD.price  != null ? `$${fmt.compact(Math.round(mkt.GOLD.price))}` : null, c:mkt.GOLD.chg },
            { l:"BTC",     v: mkt.BTC.price   != null ? `$${fmt.compact(Math.round(mkt.BTC.price))}`  : null, c:mkt.BTC.chg },
          ].map(s => (
            <div key={s.l} style={{ padding:"22px 22px", background:RAISE_1, border:`1px solid ${BORDER}`, borderRadius:14 }}>
              <Eyebrow mb={10}>{s.l}</Eyebrow>
              {s.v != null ? (
                <div className="display" style={{ fontSize:30, fontWeight:600, color:TEXT_HI, letterSpacing:"-.025em", fontVariantNumeric:"tabular-nums", fontVariationSettings:"'opsz' 30", lineHeight:1 }}>{s.v}</div>
              ) : (
                <PriceSkeleton w={120} h={28} radius={6} />
              )}
              <div style={{ fontSize:13, marginTop:8, fontWeight:600, color: (s.c ?? 0) >= 0 ? GREEN : DANGER }}>
                {s.c != null ? `${fmt.arrow(s.c)} ${fmt.signedPct(s.c)}` : "awaiting live…"}
              </div>
            </div>
          ))}
        </div>
        <div style={{ padding:"22px 26px", background:`linear-gradient(135deg, ${alpha(AMBER, .06)}, transparent 60%)`, border:`1px solid ${alpha(AMBER, .28)}`, borderRadius:14 }}>
          <Eyebrow mb={10} color={AMBER}>US National Gas Avg</Eyebrow>
          {gas?.national != null ? (
            <>
              <div className="display" style={{ fontSize:46, fontWeight:600, color:AMBER, lineHeight:1, letterSpacing:"-.03em", fontVariantNumeric:"tabular-nums" }}>${gas.national.toFixed(3)}</div>
              <div style={{ fontSize:13, color:DANGER, marginTop:8, fontWeight:500 }}>↑ +{(((gas.national-3.42)/3.42)*100).toFixed(0)}% since Feb 28 baseline ($3.42)</div>
              {gas?.diesel != null && (
                <div style={{ fontSize:13, color:TEXT_BODY, marginTop:10, fontVariantNumeric:"tabular-nums" }}>
                  Diesel (national avg) <span style={{ color:AMBER, fontWeight:600 }}>${gas.diesel.toFixed(3)}</span>
                </div>
              )}
            </>
          ) : (
            <>
              <PriceSkeleton w={180} h={42} radius={6} />
              <div style={{ fontSize:13, color:TEXT_DIM, marginTop:8 }}>awaiting AAA live feed…</div>
            </>
          )}
        </div>
      </div>
    ),
    // 8. Scenario Matrix
    () => (
      <div style={{ maxWidth:1020, width:"100%" }}>
        <div style={{ display:"flex", alignItems:"center", gap:12, marginBottom:14 }}>
          <span style={{ fontSize:18 }}>{scenarioCard.icon}</span>
          <Eyebrow mb={0} color={scenarioCard.color}>{scenarioCard.lens}</Eyebrow>
        </div>
        <div className="display" style={{ fontSize:28, fontWeight:600, color:TEXT_HI, marginBottom:22, letterSpacing:"-.015em", fontVariationSettings:"'opsz' 28", lineHeight:1.25 }}>
          {scenarioCard.title}
        </div>
        <div style={{ display:"flex", flexDirection:"column", gap:14, maxHeight:"58vh", overflowY:"auto", paddingRight:8 }}>
          {scenarioCard.body.split("\n\n").map((para, i) => {
            const [head, ...rest] = para.split(": ");
            if (rest.length && head === head.toUpperCase() && head.length < 90) {
              return (
                <div key={i} style={{ padding:"14px 18px", background:RAISE_1, border:`1px solid ${BORDER}`, borderRadius:10 }}>
                  <M style={{ fontSize:11, color:scenarioCard.color, fontWeight:700, letterSpacing:".14em", display:"block", marginBottom:6, textTransform:"uppercase" }}>{head}</M>
                  <div style={{ fontSize:13.5, color:TEXT_BODY, lineHeight:1.65 }}>{rest.join(": ")}</div>
                </div>
              );
            }
            return <div key={i} style={{ fontSize:13.5, color:TEXT_BODY, lineHeight:1.65 }}>{para}</div>;
          })}
        </div>
      </div>
    ),
  ];
  const slideTitles = [
    "Lead Development",
    "WW3 + Escalation",
    "Active Theaters",
    "Key Developments",
    "Last 14 Days",
    "Chessboard",
    "Markets",
    "Scenario Matrix",
  ];

  return (
    <>
      <div className="drawer-overlay" style={{ position:"fixed", inset:0, background:"var(--bg)", zIndex:400 }} />
      <div
        ref={dlgRef}
        role="dialog"
        aria-modal="true"
        aria-label="Briefing Mode"
        tabIndex={-1}
        style={{
          position:"fixed", inset:0, zIndex:401,
          background:`radial-gradient(80% 90% at 50% 0%, ${alpha(ww3Color, .06)}, transparent 60%), var(--bg)`,
          padding:"7vh 8vw", display:"flex", flexDirection:"column",
          fontFamily:SANS, outline:"none",
        }}
      >
        {/* Top bar */}
        <div style={{ display:"flex", alignItems:"center", gap:14, marginBottom:24 }}>
          <div style={{ display:"flex", alignItems:"center", gap:8, padding:"4px 12px", borderRadius:999, background:alpha(DANGER, .10), border:`1px solid ${alpha(DANGER, .28)}` }}>
            <span style={{ width:7, height:7, borderRadius:"50%", background:DANGER, animation:"ping 1.4s ease infinite" }} />
            <M style={{ fontSize:FS.xs, color:DANGER, fontWeight:700, letterSpacing:".18em" }}>BRIEFING</M>
          </div>
          <span style={{ fontSize:13, fontWeight:600, color:TEXT_HI }}>Global Conflict Monitor</span>
          <span style={{ fontSize:12, color:TEXT_DIM }}>· {slideTitles[slide]}</span>
          <div style={{ flex:1 }} />
          <M style={{ fontSize:11, color:TEXT_DIM, fontVariantNumeric:"tabular-nums", letterSpacing:".10em" }}>
            <span style={{ color:TEXT_HI, fontWeight:600 }}>{slide+1}</span> / 8
          </M>
          <button
            onClick={onClose}
            className="pressable"
            aria-label="Exit briefing"
            style={{
              width:36, height:36, borderRadius:8,
              background:RAISE_1, border:`1px solid ${BORDER}`,
              color:TEXT_MID, fontSize:14, cursor:"pointer",
              display:"inline-flex", alignItems:"center", justifyContent:"center",
            }}
            onMouseEnter={e => { e.currentTarget.style.background = RAISE_2; e.currentTarget.style.color = TEXT_HI; }}
            onMouseLeave={e => { e.currentTarget.style.background = RAISE_1; e.currentTarget.style.color = TEXT_MID; }}
          >
            <Icon name="close" size={16} />
          </button>
        </div>

        {/* Slide content */}
        <div key={slide} className="brief-slide" style={{ flex:1, overflowY:"auto", minHeight:0 }}>
          <div style={{ minHeight:"100%", display:"flex", alignItems:"center", justifyContent:"center", padding:"16px 0", boxSizing:"border-box" }}>
            {slides[slide]()}
          </div>
        </div>

        {/* Bottom bar — slide dots + chevrons */}
        <div style={{ display:"flex", alignItems:"center", gap:14, marginTop:18 }}>
          <button
            onClick={() => setSlide(s => Math.max(0, s - 1))}
            disabled={slide === 0}
            className="pressable"
            aria-label="Previous slide"
            style={{
              width:38, height:38, borderRadius:10,
              background: slide === 0 ? "transparent" : RAISE_1,
              border:`1px solid ${slide === 0 ? "transparent" : BORDER}`,
              color: slide === 0 ? TEXT_DIM : TEXT_BODY,
              cursor: slide === 0 ? "not-allowed" : "pointer",
              opacity: slide === 0 ? .35 : 1,
              display:"inline-flex", alignItems:"center", justifyContent:"center",
              fontFamily:SANS, fontSize:18,
            }}
          >‹</button>
          <div style={{ display:"flex", gap:6 }}>
            {slides.map((_, i) => (
              <button
                key={i}
                onClick={() => setSlide(i)}
                aria-label={`Slide ${i+1}: ${slideTitles[i]}`}
                style={{
                  width: i === slide ? 26 : 8, height:8, borderRadius:999,
                  background: i === slide ? ww3Color : RAISE_3,
                  border:"none", cursor:"pointer", padding:0,
                  transition:"width .2s cubic-bezier(.2,.8,.2,1), background .2s ease",
                }}
              />
            ))}
          </div>
          <button
            onClick={() => setSlide(s => Math.min(7, s + 1))}
            disabled={slide === 7}
            className="pressable"
            aria-label="Next slide"
            style={{
              width:38, height:38, borderRadius:10,
              background: slide === 7 ? "transparent" : RAISE_1,
              border:`1px solid ${slide === 7 ? "transparent" : BORDER}`,
              color: slide === 7 ? TEXT_DIM : TEXT_BODY,
              cursor: slide === 7 ? "not-allowed" : "pointer",
              opacity: slide === 7 ? .35 : 1,
              display:"inline-flex", alignItems:"center", justifyContent:"center",
              fontFamily:SANS, fontSize:18,
            }}
          >›</button>
          <div style={{ flex:1 }} />
          <M style={{ fontSize:FS.xs, color:TEXT_DIM, letterSpacing:".06em" }}>
            <kbd style={{ fontFamily:MONO, fontSize:FS.xs, color:"inherit", padding:"1px 6px", borderRadius:3, background:RAISE_2, border:`1px solid ${BORDER}`, marginRight:6 }}>←</kbd>
            <kbd style={{ fontFamily:MONO, fontSize:FS.xs, color:"inherit", padding:"1px 6px", borderRadius:3, background:RAISE_2, border:`1px solid ${BORDER}` }}>→</kbd>
            <span style={{ margin:"0 8px" }}>navigate</span>
            <kbd style={{ fontFamily:MONO, fontSize:FS.xs, color:"inherit", padding:"1px 6px", borderRadius:3, background:RAISE_2, border:`1px solid ${BORDER}` }}>Esc</kbd>
            <span style={{ marginLeft:6 }}>exit</span>
          </M>
        </div>
      </div>
    </>
  );
}

function App() {
  // Hydrate from localStorage cache so a cold reload shows last-known-good
  // prices immediately (with a staleness label) instead of skeletons. The next
  // live fetch upgrades the values in place.
  const [mktLive, setMktLive]           = useState(() => {
    const c = priceCache.read();
    const seed = { ...MKT };
    // Seed every cached market symbol (not just BRENT) so a cold reload shows the last
    // real close instead of a skeleton. The next live fetch upgrades each in place.
    for (const tile of ["SPX", "DOW", "NDX", "GOLD", "WTI", "BRENT"]) {
      const e = c?.[tile];
      if (e && e.price != null) {
        seed[tile] = { price: e.price, chg: e.chg ?? 0, loaded: true, asOf: e.asOf, fromCache: true };
      }
    }
    return seed;
  });
  const [gasLive, setGasLive]           = useState(() => {
    const c = priceCache.read().gas;
    if (!c) return GAS;
    return {
      national:   c.national   ?? null,
      california: c.california ?? null,
      ohio:       c.ohio       ?? null,
      cincinnati: c.cincinnati ?? null,
      diesel:       c.diesel       ?? null,
      dieselLadder: c.dieselLadder ?? null,
      asOf:       c.asOf,
      loaded:     c.national != null,
      fromCache:  true,
    };
  });
  const [ww3Live, setWw3Live]           = useState(WW3_PCT);
  const [themesLive, setThemesLive]     = useState(INIT_THEMES);
  const [breaking, setBreaking]         = useState(INIT_BREAKING);
  const [news, setNews]                 = useState(INIT_NEWS);
  const [tab, setTabRaw]                = useState("overview");
  const [refreshing, setRefreshing]     = useState(false);
  const [refreshCount, setRefreshCount] = useState(0);
  const [refreshErr, setRefreshErr]     = useState(null);
  const [lastUpdate, setLastUpdate]     = useState(BASE_LAST_UPDATE);
  const [sourceStatus, setSourceStatus] = useState({ crypto:"idle", markets:"idle", gas:"idle", news:"idle" });
  const [drawerCountry, setDrawerCountry] = useState(null);
  const [feedNav, setFeedNav]           = useState({ country:null, view:null });
  // When a lead card's "See full strategic analysis →" deep-links into the Analysis
  // tab, this holds the target arc (e.g. "iran-hormuz") so AITab can scroll to +
  // highlight the matching card. Cleared once consumed.
  const [analysisTarget, setAnalysisTarget] = useState(null);
  // Always default to dark on page load. Intentionally ignore any prior
  // localStorage value and OS preference — the dashboard is dark-first.
  const [themePref, setThemePref]       = useState("dark");
  const [paletteOpen, setPaletteOpen]   = useState(false);
  const [briefingOpen, setBriefingOpen] = useState(false);
  const [glanceOpen, setGlanceOpen]     = useState(false);
  const [kpiExpanded, setKpiExpanded]   = useState(false);
  const [lastRefreshAt, setLastRefreshAt] = useState(() => new Date()); // for relative-time display
  // Single heartbeat that drives MarketBar (mobile rotation) and BreakingTicker in lockstep.
  const [headerTick, setHeaderTick] = useState(0);
  useEffect(() => {
    const t = setInterval(() => setHeaderTick(k => k + 1), 4200);
    return () => clearInterval(t);
  }, []);
  // Clear any stale strike-window expiry left in localStorage from the previous
  // live-countdown implementation. Safe to remove this once no users have the
  // stale key set.
  useEffect(() => { try { localStorage.removeItem("wargame.strikeWindowExpiry"); } catch (_) {} }, []);

  // "Since your last visit": capture the PRIOR visit once (before overwriting) so the
  // Overview panel can diff against it, then stamp the new visit. App is the root and is
  // NOT remounted on tab switches (unlike <main key={tab}>), so this fires exactly once.
  const priorVisitRef = useRef(visitStore.read());
  const priorVisit = priorVisitRef.current;
  useEffect(() => { visitStore.write(); }, []);

  // Apply theme on mount + whenever pref changes. No persistence, no OS sync —
  // dark is the default every page load.
  useEffect(() => { applyTheme(themePref); }, [themePref]);
  const conflictDay = Math.floor((NOW - WAR_START) / 86400000);
  const ww3Color = ww3Live > 60 ? DANGER : ww3Live > 40 ? AMBER : GREEN;
  // Same measured delta as the hero chip (build.js ww3_delta), not a build-day sparkline diff.
  const ww3Delta = WW3_DELTA != null ? WW3_DELTA : (ww3Live - WW3_HISTORY[WW3_HISTORY.length - 2]);

  // Per-tab scroll memory: keyed map of saved page scrollTop values.
  // Desktop restores position when returning to a tab; mobile keeps scroll-to-top.
  const scrollMemory = useRef({});
  const isMobileScroll = () => window.innerWidth < 768;
  const getScroll = () => document.body.scrollTop || document.documentElement.scrollTop;
  const setScroll = (top) => {
    document.body.scrollTop = top;
    document.documentElement.scrollTop = top;
  };

  const setTab = useCallback((next, arcTarget = null) => {
    // Save outgoing tab's position (desktop only)
    if (!isMobileScroll()) scrollMemory.current[tab] = getScroll();

    // Deep-link target for the Analysis tab (set by lead-card "See full strategic
    // analysis →"); AITab consumes it to scroll/highlight the matching arc card.
    setAnalysisTarget(arcTarget);

    setTabRaw(next);

    // When deep-linking with a target arc, AITab scrolls to the matching card —
    // skip the default scroll-restore so the two don't fight over the viewport.
    if (arcTarget) return;

    // After React commits the new panel: restore saved position (desktop) or go to top (mobile).
    // Double rAF lets layout settle before we apply the scroll.
    requestAnimationFrame(() => requestAnimationFrame(() => {
      if (isMobileScroll()) {
        setScroll(0);
      } else {
        setScroll(scrollMemory.current[next] || 0);
      }
    }));
  }, [tab]); // tab in deps so we capture the correct outgoing tab

  const openCountry = useCallback((c) => setDrawerCountry(c), []);
  const closeDrawer = useCallback(() => setDrawerCountry(null), []);
  const onDrawerNavigate = useCallback((toTab, opts = {}) => {
    if (toTab === "feed") {
      setFeedNav({ country: opts.country || null, view: opts.view || "news" });
      setTab("feed");
      setDrawerCountry(null);
    }
  }, [setTab]);

  const doRefresh = useCallback(() => {
    setLastRefreshAt(new Date());
    fetchUpdate(setMktLive,setGasLive,setWw3Live,setThemesLive,setBreaking,setNews,setRefreshing,setRefreshCount,setRefreshErr,setLastUpdate,setSourceStatus);
  }, []);

  // Mobile UX hooks
  const isMobile = useIsMobile(900);
  const ptr = usePullToRefresh(doRefresh, isMobile);
  const swipe = useSwipeTabs(tab, setTab, TABS, isMobile);

  // Live-price lifecycle: one fetch on mount, then a 5-minute auto-refresh.
  // The auto-refresh skips when the tab is backgrounded (no point burning
  // mobile data on a hidden tab), and runs immediately when the tab returns
  // to the foreground so users see fresh prices instead of cached ones.
  // Delegating to doRefresh keeps a single source of truth for the fetch
  // pipeline — partial-success handling, cache writes, and the Cincinnati
  // fetch all live in fetchUpdate now.
  useEffect(() => {
    doRefresh();
    const REFRESH_MS = 5 * 60 * 1000;
    const intervalId = setInterval(() => {
      if (typeof document !== "undefined" && document.visibilityState !== "visible") return;
      doRefresh();
    }, REFRESH_MS);
    const onVis = () => {
      if (document.visibilityState === "visible") doRefresh();
    };
    if (typeof document !== "undefined") {
      document.addEventListener("visibilitychange", onVis);
    }
    return () => {
      clearInterval(intervalId);
      if (typeof document !== "undefined") document.removeEventListener("visibilitychange", onVis);
    };
  }, [doRefresh]);

  // Keyboard shortcuts: ⌘K palette, 1–6 to switch tabs, Escape to close drawer.
  useEffect(() => {
    function onKey(e) {
      // ⌘K / Ctrl+K — open command palette (works even from inputs)
      if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === "k") {
        e.preventDefault();
        setPaletteOpen(o => !o);
        return;
      }
      if (e.key === "Escape" && drawerCountry) { setDrawerCountry(null); return; }
      const tag = (e.target?.tagName || "").toLowerCase();
      if (tag === "input" || tag === "textarea" || tag === "select") return;
      if (e.metaKey || e.ctrlKey || e.altKey) return;
      // B — toggle Briefing Mode
      if (e.key.toLowerCase() === "b") {
        e.preventDefault();
        setBriefingOpen(o => !o);
        return;
      }
      const n = parseInt(e.key, 10);
      if (n >= 1 && n <= TABS.length) {
        e.preventDefault();
        setTab(TABS[n - 1]);
      }
    }
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [drawerCountry, setTab]);

  const renderTab = () => {
    switch(tab) {
      case "overview": return <OverviewTab mkt={mktLive} gas={gasLive} ww3={ww3Live} themes={themesLive} openCountry={openCountry} setTab={setTab} />;
      case "feed":     return <FeedTab news={news} openCountry={openCountry} initialCountry={feedNav.country} initialView={feedNav.view} priorVisit={priorVisit} />;
      case "actors":   return <ActorsTab openCountry={openCountry} />;
      case "economy":  return <EconomyTab mkt={mktLive} gas={gasLive} openCountry={openCountry} />;
      case "analysis": return <AITab targetArc={analysisTarget} onConsumeTarget={() => setAnalysisTarget(null)} />;
      case "outlook":  return <OutlookTab openCountry={openCountry} />;
      default:         return null;
    }
  };

  const latestHeadline = breaking.length > 0 ? breaking[0] : (news.length > 0 ? news[0].h : null);

  return (
    <div style={{ fontFamily:SANS, background:BG, minHeight:"100vh", color:TEXT_BODY }}>

      {/* Pull-to-refresh indicator (mobile) */}
      {isMobile && <PullToRefreshIndicator state={ptr.state} pullY={ptr.pullY} />}

      {/* Header — persistent context strip */}
      <header className="header-row" style={{ position:"sticky", top:0, zIndex:100, minHeight:60, display:"flex", alignItems:"center", justifyContent:"space-between", padding:"0 22px", background:"var(--header-bg)", backdropFilter:"blur(14px)", WebkitBackdropFilter:"blur(14px)", borderBottom:`1px solid ${BORDER}`, gap:14, flexWrap:"wrap" }}>
        <div className="choreographed" style={{ animationDelay:"0ms", display:"flex", alignItems:"center", gap:14, minHeight:60, flexShrink:0 }}>
          <div style={{ display:"flex", alignItems:"center", gap:7, background:alpha(DANGER, .12), border:`1px solid ${alpha(DANGER, .28)}`, borderRadius:999, padding:"3px 10px" }}>
            <span style={{ width:6, height:6, borderRadius:"50%", background:DANGER, animation:"ping 1s ease infinite" }} />
            <M style={{ fontSize:FS.xs, color:DANGER, fontWeight:600, letterSpacing:".12em" }}>LIVE</M>
          </div>
          <div className="header-title-stack" style={{ display:"flex", flexDirection:"column", lineHeight:1.15, minWidth:0 }}>
            <span className="header-title" style={{ fontSize:14, fontWeight:600, color:TEXT_HI, letterSpacing:"-.005em", whiteSpace:"nowrap", overflow:"hidden", textOverflow:"ellipsis" }}>Global Conflict Monitor</span>
            <span className="header-subtitle" style={{ fontSize:11, color:TEXT_DIM, letterSpacing:".04em" }}>Operation Epic Fury · US-BRICS Rivalry · Russia-Ukraine</span>
          </div>
        </div>

        {/* Persistent context strip — survives every tab */}
        <div className="header-context-mobile-hide choreographed" style={{ animationDelay:"160ms", display:"flex", alignItems:"center", gap:0, flex:1, justifyContent:"center", minWidth:0, maxWidth:760 }}>
          <button
            onClick={() => setTab("overview")}
            title="Go to Overview"
            style={{
              display:"flex", flexDirection:"column", alignItems:"flex-start", gap:1,
              padding:"6px 14px",
              background:RAISE_1, border:`1px solid ${BORDER}`, borderRight:"none",
              borderRadius:"8px 0 0 8px",
              cursor:"pointer", color:TEXT_BODY,
              fontFamily:SANS, textAlign:"left",
            }}
          >
            <M style={{ fontSize:FS.xs, color:TEXT_DIM, letterSpacing:".1em", fontWeight:600, textTransform:"uppercase" }}>Day</M>
            <M style={{ fontSize:14, color:TEXT_HI, fontWeight:600, fontVariantNumeric:"tabular-nums", letterSpacing:"-.01em" }}>{conflictDay}</M>
          </button>
          <button
            onClick={() => { setTab("overview"); requestAnimationFrame(() => window.scrollTo({ top: 9999, behavior:"smooth" })); }}
            title="Go to escalation ladder"
            style={{
              display:"flex", flexDirection:"column", alignItems:"flex-start", gap:1,
              padding:"6px 14px",
              background:`linear-gradient(135deg, ${alpha(ww3Color, .08)}, transparent 60%)`,
              border:`1px solid ${BORDER}`,
              borderRadius:"0 8px 8px 0",
              cursor:"pointer", color:TEXT_BODY,
              fontFamily:SANS, textAlign:"left",
            }}
          >
            <M style={{ fontSize:FS.xs, color:TEXT_DIM, letterSpacing:".1em", fontWeight:600, textTransform:"uppercase" }}>WW3</M>
            <div style={{ display:"flex", alignItems:"baseline", gap:6 }}>
              <M style={{ fontSize:14, color:ww3Color, fontWeight:600, fontVariantNumeric:"tabular-nums", letterSpacing:"-.01em" }}>{ww3Live}%</M>
              <M style={{ fontSize:FS.xs, color: ww3Delta >= 0 ? DANGER : GREEN, fontWeight:500 }}>{ww3Delta >= 0 ? "↑+" : "↓"}{Math.abs(ww3Delta)}</M>
            </div>
          </button>
        </div>

        <div className="choreographed header-actions" style={{ animationDelay:"280ms", display:"flex", alignItems:"center", gap:10, minHeight:60, flexShrink:0 }}>
          <FreshnessIndicator sources={sourceStatus} lastRefreshAt={lastRefreshAt} refreshErr={refreshErr} />
          <ThemeToggle pref={themePref} onChange={setThemePref} />
          <button
            onClick={doRefresh}
            disabled={refreshing}
            className="iconbtn pressable refresh-btn"
            aria-label={refreshing ? "Refreshing" : "Refresh data"}
            title={refreshing ? "Fetching live sources…" : `Refresh data (last refreshed ${Math.round((Date.now() - lastRefreshAt.getTime()) / 60000)}m ago)`}
            style={{
              fontFamily:SANS, fontSize:12, fontWeight:600, letterSpacing:".02em",
              color: refreshing ? TEXT_DIM : AMBER,
              background: refreshing ? RAISE_1 : alpha(AMBER, .08),
              border:`1px solid ${refreshing ? RAISE_3 : alpha(AMBER, .32)}`,
              borderRadius: 8,
              padding:"7px 14px",
              cursor: refreshing ? "not-allowed" : "pointer",
              display:"flex", alignItems:"center", gap:8,
              position:"relative", overflow:"hidden",
            }}
          >
            <span style={{
              display:"inline-flex", alignItems:"center", justifyContent:"center",
              width:14, height:14, position:"relative",
            }}>
              <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={refreshing ? "spin" : ""}>
                <path d="M3 12a9 9 0 0 1 15.5-6.36L21 8" />
                <path d="M21 3v5h-5" />
                <path d="M21 12a9 9 0 0 1-15.5 6.36L3 16" />
                <path d="M3 21v-5h5" />
              </svg>
            </span>
            <span className="btn-label-desktop">{refreshing ? "Refreshing…" : "Refresh"}</span>
          </button>
        </div>
      </header>

      <MarketBar mkt={mktLive} ww3={ww3Live} tick={headerTick} />
      <BreakingTicker headlines={breaking} tick={headerTick} onClick={() => { setFeedNav({ country: null, view: "news" }); setTab("feed"); }} />

      <div style={{ display:"flex", alignItems:"flex-start" }}>
        <SideNav tab={tab} setTab={setTab} sources={sourceStatus} />
        <main
          key={tab}
          id={`panel-${tab}`}
          role="tabpanel"
          aria-labelledby={`tab-${tab}`}
          className="tab-content main-pad"
          style={{
            flex:1, minWidth:0, maxWidth:1240, margin:"0 auto", padding:"28px 36px 80px",
            transform: isMobile && swipe.swiping ? `translateX(${swipe.offsetX}px)` : undefined,
            transition: isMobile && swipe.swiping ? "none" : "transform .3s cubic-bezier(.2,.8,.2,1)",
            willChange: isMobile ? "transform" : undefined,
          }}
        >
          {renderTab()}
        </main>
      </div>

      <StatusBar
        sources={sourceStatus}
        lastRefreshAt={lastRefreshAt}
        ww3={ww3Live}
        tab={tab}
        theme={resolveTheme(themePref)}
        onPaletteOpen={() => setPaletteOpen(true)}
        onBriefingOpen={() => setBriefingOpen(true)}
      />

      <BottomTabBar tab={tab} setTab={setTab} />

      {/* Glance mode FAB — mobile only */}
      {isMobile && !glanceOpen && !briefingOpen && (
        <button
          className="glance-fab"
          onClick={() => setGlanceOpen(true)}
          aria-label="Quick glance"
          title="Quick glance view"
        >
          <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
            <circle cx="12" cy="12" r="10" /><path d="M12 6v6l4 2" />
          </svg>
        </button>
      )}

      {/* Country drawer — bottom sheet on mobile, side drawer on desktop */}
      {drawerCountry && isMobile && (
        <CountryBottomSheet country={drawerCountry} onClose={closeDrawer} onNavigate={onDrawerNavigate} />
      )}
      {drawerCountry && !isMobile && (
        <CountryDrawer country={drawerCountry} onClose={closeDrawer} onNavigate={onDrawerNavigate} />
      )}

      <CommandPalette
        open={paletteOpen}
        onClose={() => setPaletteOpen(false)}
        setTab={setTab}
        setThemePref={setThemePref}
        themePref={themePref}
        doRefresh={doRefresh}
        openCountry={openCountry}
        openBriefing={() => setBriefingOpen(true)}
      />

      <GlanceMode
        active={glanceOpen}
        onClose={() => setGlanceOpen(false)}
        ww3={ww3Live}
        mkt={mktLive}
        gas={gasLive}
        conflictDay={conflictDay}
        latestHeadline={latestHeadline}
      />

      <BriefingMode
        active={briefingOpen}
        onClose={() => setBriefingOpen(false)}
        ww3={ww3Live}
        mkt={mktLive}
        gas={gasLive}
        conflictDay={conflictDay}
      />
    </div>
  );
}

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(<App />);